const pages={"": "<div class=\"page-shell knowing-page bv-page bv-gateway\"><nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/\">首页</a><span>/</span><a href=\"#/ren\">人道</a><span>/</span><a href=\"#/knowing\">认识自己</a><span>/</span><span aria-current=\"page\">身体载具我</span></nav><nav aria-label=\"认识自己的三个层面\" class=\"bv-position\"><span aria-current=\"page\">身体载具我</span><a href=\"#/knowing/external-self\">外在角色我</a><a href=\"#/knowing/inner-consciousness\">内在意识我</a></nav><header class=\"bv-index-head\"><p class=\"bv-kicker\">人道 · 认识自己</p><h1>身体载具我</h1><p class=\"bv-question\">你经由什么认识自己？<br>又经由什么创造自己？</p><p class=\"bv-index-deck\">身体，是生命在这个世界里体验、表达和行动的活的载具。<br>认识它，是理解自己的生命怎样运行、学会与整个自己合作的起点。</p></header><section class=\"bv-entry-grid\" aria-label=\"进入三个独立篇章\"><a class=\"bv-entry\" href=\"#/knowing/body-self/recognition\"><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/recognition.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"树下的人触地持叶，身体与河流、土地相遇\"><figcaption></figcaption></figure><div class=\"bv-entry-copy\"><span class=\"bv-kicker\">第一部 / 01</span><h2>认识身体</h2><p>承载着我的生命，怎样活着？</p><small>身体有自己的生命与秩序。认识它的形态、运行与节律，也是认识自己的开始。</small><span class=\"bv-entry-link\">进入本篇 <i aria-hidden=\"true\">↗</i></span></div></a><a class=\"bv-entry\" href=\"#/knowing/body-self/experience\"><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/experience.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"双手塑造陶器，触碰与调整带来新的形状\"><figcaption></figcaption></figure><div class=\"bv-entry-copy\"><span class=\"bv-kicker\">第二部 / 02</span><h2>理解身体</h2><p>体验与创造，怎样在这里发生？</p><small>世界经由身体成为体验；选择经由行动进入现实，新的体验又使我们重新认识自己。</small><span class=\"bv-entry-link\">进入本篇 <i aria-hidden=\"true\">↗</i></span></div></a><a class=\"bv-entry\" href=\"#/knowing/body-self/cooperation\"><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/cooperation.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"照料花园的人在树下停步，工具与清水放在身旁\"><figcaption></figcaption></figure><div class=\"bv-entry-copy\"><span class=\"bv-kicker\">第三部 / 03</span><h2>与身体合作</h2><p>怎样让整个自己共同生活？</p><small>从察觉、辨认到回应，让方向、现实安排与身体需要形成能够持续的生活。</small><span class=\"bv-entry-link\">进入本篇 <i aria-hidden=\"true\">↗</i></span></div></a></section><div class=\"bv-index-note\"><p>从认识它怎样活着，到理解体验与选择，再把理解带进生活。<br>三篇可以依次读，也可以从眼下最关心的问题进入。</p></div><nav class=\"bv-page-turn\" aria-label=\"篇章导航\"><a href=\"#/knowing\"><small>上一页</small><span>← 认识自己</span></a><a href=\"#/knowing/body-self/recognition\"><small>继续阅读</small><span>第一部 · 认识身体 →</span></a></nav></div>", "recognition": "<div class=\"page-shell knowing-page bv-page bv-part-page\"><nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/\">首页</a><span>/</span><a href=\"#/ren\">人道</a><span>/</span><a href=\"#/knowing\">认识自己</a><span>/</span><a href=\"#/knowing/body-self\">身体载具我</a><span>/</span><span aria-current=\"page\">认识身体</span></nav><nav class=\"bv-chapter-nav\" aria-label=\"身体载具我阅读路径\"><a href=\"#/knowing/body-self\" >导读</a><a href=\"#/knowing/body-self/recognition\" aria-current=\"page\"><small>01</small>认识身体</a><a href=\"#/knowing/body-self/experience\" ><small>02</small>理解身体</a><a href=\"#/knowing/body-self/cooperation\" ><small>03</small>与身体合作</a></nav><header class=\"bv-hero\"><div><p class=\"bv-kicker\">身体载具我 · 第一部 / 01</p><h1>认识身体</h1><p class=\"bv-question\">承载着我的生命，怎样活着？</p><p class=\"bv-deck\">身体有自己的生命与秩序。认识它的形态、运行与节律，也是认识自己的开始。</p></div><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/recognition.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"树下的人触地持叶，身体与河流、土地相遇\"><figcaption>认识身体</figcaption></figure></header><details class=\"bv-fold bv-onpage\"><summary>本篇目录</summary><nav aria-label=\"本篇章节\"><a href=\"#bv-s01\" data-scroll=\"bv-s01\">01 身体，承载着我的生命</a><a href=\"#bv-s02\" data-scroll=\"bv-s02\">02 生命在怎样维持自己</a><a href=\"#bv-extensions\" data-scroll=\"bv-extensions\">思想来源与延伸阅读</a></nav></details><div class=\"bv-prose\"><details class=\"bv-fold bv-reading-note\"><summary>怎样阅读本篇的研究与思想来源？</summary><div class=\"bv-fold-body\"><p>主线正文可以独立阅读。带“+”的部分默认收起，展开可阅读延伸案例、研究讨论与原资料。</p><p><span class=\"lv l1\">研究参考</span>引用研究与科学资料，需结合研究范围理解；<span class=\"lv l2\">结论有争议</span>提示已有不同解释；<span class=\"lv l3\">体系主张</span>提示三道哲学或所引资料的哲学解释。三者的提示会一直保留。</p></div></details><article aria-label=\"认识身体正文\"><details class=\"bv-fold\" id=\"bv-prologue\"><summary>为什么从身体开始？每天一场马拉松</summary><div class=\"bv-fold-body\"><section aria-labelledby=\"bv-prologue\" class=\"bv-section\">\n<p>十九岁那年，英国青年伊恩·沃特曼发了一场高烧。烧退了，他的身体却不再听他的了。</p>\n<p>一场自身免疫反应，毁掉了他脖子以下的感觉神经。他的肌肉完好，并没有瘫痪。可他再也感觉不到自己的手脚在哪里，也感觉不到它们碰到了什么。他坐不起来，站不起来，连自己吃饭都做不到。医生说，他下半辈子要在轮椅上过。</p>\n<p>他没有接受。接下来的许多年里，他一个动作一个动作地重新学：用眼睛盯着自己的腿，在心里算好每一步，再把脚一点一点放下去。他学会了站，学会了走，学会了写字。可是每一个动作，都得看着、想着才能完成。他自己说，他的走路是一种“有控制的跌倒”。只要看不见自己的手脚，他就控制不住它们，连站稳都难。</p>\n<p>为他看了多年病的神经科医生乔纳森·科尔，后来写了一本书讲他的故事，书名叫《骄傲与每日马拉松》。</p>\n<p>我们每个人每天也在跑这场马拉松，只是替我们跑的是身体。</p>\n<p>沃特曼重新学会的，也不只是走路。感觉断掉以后，世界跟着变远了：杯子握在手里，他却不知道自己握着；地面就在脚下，他要低头去看，才敢落脚。这个故事把一件平时看不见的事摆到了眼前。世界要经由身体，才进得来；一个人想做的事，也要经由身体，才做得出去。</p>\n<p>《三道哲学》说，生命的意义在于通过体验认识自己，通过选择创造自己。体验，需要一个能感受的地方；选择，需要一个能行动的地方。这两件事，都发生在这具身体里。</p>\n<p>《三道哲学》从三个相互关联的层面认识同一个生命：</p>\n<ul class=\"plain\">\n<li><b>身体载具我</b>：这具身体。你在这个世界里的一切经历，都经由它发生。</li>\n<li><b>外在角色我</b>：有名字、有身份、有故事线的那个“我”。我们平时说“我”，指的几乎都是它。</li>\n<li><b>内在意识我</b>：本体系所说的更深的意识与方向来源。它能觉察角色的经历，也不被眼前的身份完全界定。</li>\n</ul>\n<p>身体让生命得以感受和行动，角色使生命在关系与身份中展开，内在意识我则指向本体系所理解的更深来源。这一章从身体讲起。它离你最近，最具体，也最容易被当成理所当然。</p>\n<p class=\"lines big\">身体载具我，是生命在这个世界里<br/>体验、表达和行动的活的载具。<br/>认识它，是理解自己的生命怎样运行、<br/>学会与整个自己合作的起点。</p>\n</section></div></details><figure class=\"fig bv-life-map\"><p class=\"ttl\">同一个生命 · 三个关联层面</p><div class=\"bv-life-grid\"><div class=\"active\"><span>此篇的起点</span><h6>身体载具我</h6><p>感受 · 调节 · 行动</p></div><div><span>现实中的展开</span><h6>外在角色我</h6><p>身份 · 关系 · 安排</p></div><div><span>本体系的方向来源</span><h6>内在意识我</h6><p>觉察 · 意义 · 引领</p></div></div><figcaption>三个层面在生活中相互影响；图示用于理解关系，不把它们分成三个彼此隔离的人。</figcaption></figure><section aria-labelledby=\"bv-s01\" class=\"bv-section\"><h3 id=\"bv-s01\"><span class=\"n\">01</span>身体，承载着我的生命</h3>\n<p>手指被门夹住的那一秒，你不会想“我的手受伤了”，你只是疼。久别的人一把抱住你，你也不会先去分析肩膀承受了多少压力。累到极点的晚上，全身都是沉的；奔跑的时候，风从耳边过去。这些时刻里，没有一个“你”站在身体旁边看着它。你就在那里。</p>\n<p>可另一些时候，你又确实站在旁边看着它：照镜子，看体检报告，给它买一双合脚的跑鞋。</p>\n<h4>有一个身体，也是一个身体</h4>\n<p>我们把这一层叫作“身体载具我”。这个名字里装着两件看起来矛盾的事。</p>\n<p><strong>“载具”说的是“有”。</strong>它载着你在这个世界里移动。你可以好好保养它，也可以用得太狠。</p>\n<p><strong>“我”说的是“是”。</strong>你没法从它里面走出来。牙疼的时候，不是“我的身体”在疼，是我在疼。</p>\n<p>德国哲学家普莱斯纳把这种双重性说得很准：人总是同时“是”一个活的身体，又“拥有”这个身体，把它当作一件可以使用的东西。我们一整天都在两者之间切换。跑步、拥抱、大笑的时候，你就是身体；照镜子、看体检报告的时候，你在打量一件属于你的东西。</p>\n<figure aria-label=\"有一个身体，也是一个身体\" class=\"fig\">\n<p class=\"ttl\">同一具身体，两种视角</p>\n<div class=\"duo\">\n<div><h6>有一个身体</h6><dl><dt>它是</dt><dd>可以观察、照料、使用的对象</dd><dt>你在做的事</dt><dd>照镜子，看体检报告，安排作息，选一双跑鞋</dd><dt>对应的词</dt><dd>载具</dd></dl></div>\n<div><h6>是一个身体</h6><dl><dt>它是</dt><dd>正在经历这一切的你自己</dd><dt>你在做的事</dt><dd>疼，拥抱，疲惫，奔跑，大笑</dd><dt>对应的词</dt><dd>我</dd></dl></div>\n</div>\n<p class=\"mid\">两种视角合在一起，就是<b>活的载具</b></p>\n<figcaption>普莱斯纳说，人一整天都在这两种视角之间切换。</figcaption>\n</figure>\n<h4>活的载具</h4>\n<p>“载具”在《三道哲学》里有确切的意思。生命来到这个世界，要借一个形，才能感受、表达和行动，这个形就是载具。“活的”，是说这件载具有它自己的生命和秩序：它会自己呼吸、修补、作息，也有自己的需要和限度。它载着你，它也是你。</p>\n<p>法国哲学家梅洛-庞蒂举过一个例子。盲人用惯了手杖，就不再觉得手里握着一根棍子，他是用杖尖去碰路面的。学会开车的人也一样，开久了，轮胎压过的坑洼，好像直接压在自己身上。载具会往外延伸。人最早、也最贴身的载具，就是这具身体，后来的手杖、汽车、键盘，都是从它往外接出去的。梅洛-庞蒂的判断可以作为这一章的底色：身体，是我们拥有一个世界的方式。</p>\n<h4>三个我，看的是同一个生命</h4>\n<p>身体载具我、外在角色我、内在意识我，在本体系里是同一个生命相互关联的三个层面。用身体、角色和意识来区分，是为了看清生命中不同的需要与活动。一夜没睡好，第二天的判断可能就变了；被人当众羞辱，胃会一下缩紧；一个人找回珍视的方向，也可能重新有了行动的力量。我们的生活里，这些影响总是交织着发生。</p>\n<p>“我就是身体”，说的是疼痛、拥抱和行动中直接活着的经验；“我拥有身体”，说的是我们也能回过头来观察、照料自己。“载具”强调生命经由身体展开，“我”强调身体本身就属于正在经历的生命。两种说法并不要求我们把自己拆成驾驶者和机器。</p>\n<p class=\"read-note\"><span class=\"lv l3\">体系主张</span>三道哲学进一步认为，内在意识我不完全由肉身与角色界定。这是本体系的哲学立场。本章所引的身体与心理研究，可以帮助理解身体怎样参与生活；它们本身并不证明意识能够脱离身体存在。</p>\n<p>所以认识身体，从来不只是认识一件器物。它的形态、能力和限度，本身就是认识自己的内容：你天生有多少体力，紧张时最先绷住的是哪里，在哪一段时间最清醒，你的身体扛得住多少，又扛不住什么。</p>\n<details class=\"bv-fold\"><summary>史铁生怎样从身体的处境中认识生命？</summary><div class=\"bv-fold-body\">\n<p>1969 年，十八岁的史铁生去陕北插队。三年后，他双腿瘫痪，那年他二十一岁。回到北京以后，他常常摇着轮椅，一个人去家附近的地坛，在那里一坐就是很久。他后来在《我与地坛》里写那些年：怎样想到死，又怎样慢慢想通，死不必着急，它总会来，要想的是怎样活下去。</p>\n<p>再后来，他的肾也坏了，要定期去医院透析。他就在两次透析之间写作，后来把这段时间写下的文字结成一本书，叫《病隙碎笔》。他曾自嘲，职业是生病，业余写一点东西。</p>\n<p>史铁生的哲学，是从一具具体的身体出发的：一双不能走的腿，一副需要透析的肾，一张轮椅能去到的地方。他就在这具身体的处境里，想明白了很多人一辈子没想过的事。</p>\n<p class=\"lines\">我的生命，始终在具体的身体处境中展开。</p>\n</div></details><h4>它不需要知道自己叫什么</h4>\n<p>身体从来不需要知道自己叫什么。它不在乎你的头衔，不读你的简历，也不知道你在别人眼里是什么样子。心跳不会因为你升职而变得更有力，伤口也不会因为你是 CEO 而长得更快。守着名字和身份的，是另一个“我”，下一章会讲。</p>\n<details class=\"bv-fold\"><summary>载具，只是这具肉身吗？</summary><div class=\"bv-fold-body\">\n<p>原资料里，“载具”比肉身要宽：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">载具我不等同于肉身我：载具我是多层复合体，而肉身我只是物质层中的伪装物理载具。</p><cite class=\"src\">——JY3 第123节</cite></blockquote>\n<p>这份资料还把肉身描述为好几种意识共同运作的地方：肉身的、菌群的、头脑的，还有心思和人格片段的（Y5-4 第233节）。这是资料内部对生命的解释，“热闹的大家庭”可以帮助理解这种关系。</p>\n<p>原资料还用过一个程序员很熟悉的比喻：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">我们的载具更像是云端笔记本电脑，内在没有硬盘或系统，与老式的电脑并不相同。</p><cite class=\"src\">——Y1-4 第708节</cite></blockquote>\n<p>这个比喻用本地的维生系统说明身体的自主，用云端账号说明资料所主张的、更深的意识来源。但电脑、账号和操作者的分离，不能直接用来说明生命的结构。把它读作一种关系的比喻就好；身体在现实中怎样运行，仍须通过身体本身来认识。</p>\n<p>载具一共有多少层，见文末延伸阅读里的“原资料里的身体”。</p>\n</div></details>\n<div class=\"check\"><b>自查</b>你最近一次清楚地感到“我就是这具身体”，是在什么时候？</div>\n</section><section aria-labelledby=\"bv-s02\" class=\"bv-section\"><h3 id=\"bv-s02\"><span class=\"n\">02</span>生命在怎样维持自己</h3>\n<h4>流动的模式</h4>\n<p>控制论的创始人诺伯特·维纳说过一句话，大意是：我们不是一团持存不变的物质，而是不断延续自己的模式，就像河流里的漩涡。</p>\n<p>这不只是比喻。你的身体每天更换大约三千三百亿个细胞，每秒四百万个左右，加起来约八十克。<span class=\"lv l1\">研究参考</span>也不是所有细胞都会被替换，大部分脑神经元和眼睛晶状体里的细胞会陪你一生。可即使是它们，构成它们的分子也在不断更换。<span class=\"lv l1\">研究参考</span></p>\n<p>所以流传很广的“每七年换一个全新的你”并不准确。更准确地说，你身上几乎没有一样东西是永久的，除了那个“样子”本身。零件一直在换，样子留了下来。</p>\n<p>维持这个样子，是一件需要一刻不停去做的事。一块石头什么都不做，也能保持原样；一个活的身体一旦停止工作，几分钟内就开始瓦解。做过线上系统的人会懂：最健康的系统，能在不停机的情况下滚动更新所有实例。你的身体从出生那天起，就是这样运行的。</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">它们每一个都是你，它们又都不是你；它们组成与成就了你，又没有具体哪个达成了那个完美的你。</p><cite class=\"src\">——S1-2《自我认知的百宝箱》</cite></blockquote>\n<figure class=\"fig bv-regulation\"><p class=\"ttl\">维持生命，是一个持续的过程</p><div class=\"bv-cycle-line\"><div><b>环境与活动变化</b><span>冷热、进食、休息、运动</span></div><i aria-hidden=\"true\">→</i><div><b>身体持续调节</b><span>各系统协调与反馈</span></div><i aria-hidden=\"true\">→</i><div><b>维持可生活的范围</b><span>再依据变化继续调整</span></div></div><figcaption>这是帮助理解自主调节的概括。身体不是保持一个永远不变的数值。</figcaption></figure><h4>身体的智慧</h4>\n<p>十九世纪，法国生理学家克洛德·贝尔纳注意到，外面冷热饥饱不断变化，血液和组织液组成的“内环境”，却一直被维持在一个相当稳定的范围里。他留下一句后来被生理学界反复引用的话：</p>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">内环境的稳定，是自由生活的条件。</p><cite class=\"src\">——克洛德·贝尔纳，1878</cite></blockquote>\n<p>几十年后，美国生理学家沃尔特·坎农给这种稳定起了一个名字，叫“稳态”，又把他讲这件事的书命名为《身体的智慧》。<span class=\"lv l1\">研究参考</span></p>\n<p>心跳、呼吸、体温，还有血糖和血压，都被维持在一个很窄的区间里。<span class=\"lv l1\">研究参考</span>你不需要知道它们的正常值，它们也从不等你下命令。你准备起跑的那一刻，心率在肌肉真正缺氧之前就开始上升。切菜划破了手指，几分钟内血小板就把缺口堵上，几天后新的组织从边缘长出来。<span class=\"lv l1\">研究参考</span>整个过程里，你做的唯一一件事，可能是贴了一张创可贴。</p>\n<p>贝尔纳那句话，放在这一章里读，还有另一层意思。身体先在里面把局面稳住，人才腾得出手，到外面去体验、去选择。我们以为自由是头脑的事，它的地基却在身体里。</p>\n<p>伊恩·沃特曼每天要用意志去做的事，你的身体每一秒都在替你做，而且做得比意志好。</p>\n<h4>它有自己的时间</h4>\n<p>1962 年夏天，法国地质学家米歇尔·西弗尔下到阿尔卑斯山的一个冰川洞穴里，没有钟表，也见不到日光，独自待了大约两个月。他困了就睡，醒了就给地面打电话报告。九月中旬，地面通知他实验结束时，他以为日历才走到八月二十日。</p>\n<p>他心里的时间缩短了将近一半，他的睡和醒，却仍然大致保持着一天一轮的节律。后来的研究把这件事讲得更清楚：人体里有一套大约以二十四小时为周期的生物钟，2017 年的诺贝尔生理学或医学奖，就颁给了揭示它分子机制的三位科学家。<span class=\"lv l1\">研究参考</span>身体有它自己的时间，不完全听你的日程。</p>\n<h4>两种“自动”</h4>\n<p>身体的自动，要和另一种自动分开。开车回家，到了楼下才发现一路上想的全是别的事，路线、刹车、变道，好像都是“自己”完成的。这一种自动，是后来学会的：练过千百次的动作，加上一路形成的判断和反应。它住在身体里，却是由经历塑造的，也能被重新训练。一项日记研究估计，人一天里大约四成多的行为，是在相同的情境里习惯性地完成的。<span class=\"lv l2\">结论有争议</span></p>\n<figure aria-label=\"两种自动的对照\" class=\"fig\">\n<p class=\"ttl\">两种“自动”</p>\n<div class=\"duo\">\n<div><h6>身体维持生命的调节</h6><dl><dt>从哪里来</dt><dd>与生俱来</dd><dt>例子</dt><dd>心跳，体温，伤口愈合，困了想睡、到点会醒</dd><dt>能不能直接下命令</dt><dd>不能，只能理解它、配合它</dd><dt>在哪里讲</dt><dd>本章</dd></dl></div>\n<div><h6>成长中学会的惯性</h6><dl><dt>从哪里来</dt><dd>在经历里一遍遍练成</dd><dt>例子</dt><dd>开车，打字，说话的口头禅，一被批评就辩解</dd><dt>能不能直接下命令</dt><dd>不能立刻改，但能慢慢重新训练</dd><dt>在哪里讲</dt><dd>下一章：外在角色我</dd></dl></div>\n</div>\n<figcaption>两种自动常常一起工作，但来源不同，对待的办法也不同。</figcaption>\n</figure>\n<p>两者常常一起工作。开车时，看路和打方向盘是学来的，紧急时一脚踩下刹车、心跳骤然加快，就有身体自己的份。把两种自动混在一起，身体就会替角色背锅：明明是一套旧习惯在跑，人却以为“身体就是这样”。这一章只讲第一种，第二种留给下一章。</p>\n<details class=\"bv-fold\"><summary>原资料里的“自动驾驶”，指的是哪一种？</summary><div class=\"bv-fold-body\">\n<p>原资料说，每个角色都配有一套“自动驾驶”系统，叫“七魄”：主意识的焦点移开的时候，人照样按日常生活，吃饭上班，积累经验和生活所需（SY《失忆的归途》第十二章）。《三正道》又把七魄译成七种能力：感知力、直觉力、生育力、抵抗力、排毒、解毒、新陈代谢。</p>\n<p>可见原资料里的“自动驾驶”同时包含了两种自动。抵抗力、新陈代谢这些生理能力，属于本章说的身体调节；照常吃饭上班、按老路过日子，更多是学来的惯性，属于外在角色我。</p>\n</div></details>\n<details class=\"bv-fold\"><summary>中医怎样描述身体的自主？</summary><div class=\"bv-fold-body\">\n<p>两千多年前，《黄帝内经》就把脏腑写成了一座朝廷，各有官职：</p>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">心者，君主之官也，神明出焉。肺者，相傅之官，治节出焉。肝者，将军之官，谋虑出焉。……凡此十二官者，不得相失也。</p><cite class=\"src\">——《黄帝内经·素问·灵兰秘典论》</cite></blockquote>\n<p>十二个官职各司其职，又彼此配合。这座朝廷不靠你每天上朝，它自己在运转。第六节还会回到这座朝廷，看它什么时候安稳，什么时候会乱。</p>\n<p>中医师李辛在临床里看到的，是同一种自主：“<span class=\"q\">在我们心身放松的时候，经络系统会进入一个自动调适的状态，它自己会把不均匀的能量平衡掉</span>”。</p>\n</div></details>\n<p>所以身体不是一件工具。它会自己维持，会自己修，有自己的时间和秩序。和这样一个“我”打交道，命令是行不通的。它要的，是合作。</p>\n<p class=\"lines\">身体具有值得理解、尊重和配合的运行秩序。</p>\n<div class=\"check\"><b>自查</b>你和身体之间，现在更像上级和下属，还是搭档？</div>\n</section><section class=\"bv-section\" aria-labelledby=\"bv-extensions\"><h3 id=\"bv-extensions\">思想来源与延伸阅读</h3><details class=\"bv-fold\"><summary>原资料里的身体，有多少层？</summary><div class=\"bv-fold-body\">\n<p>前文把生活经验、研究参考和体系解释放在各自的范围内讨论。以下集中介绍原资料对多层身体的主张；其中的“能量”“三魂”“七魄”等用语，按资料内部的含义阅读，不与同名的生理或物理概念直接等同。《内证观察笔记》的作者有一句话，正好可以放在这张地图的入口：“<span class=\"q\">未知不等于神秘，玄学不玄，只是复杂，只是因为人类还不了解。</span>”</p>\n<ul class=\"plain\">\n<li><b>多层载具。</b>外在载具分为物理层、化学层、微生物层、乙太层、心理层、心灵层、电磁层，任何一层出问题，都会让身体出状况（Y2-4 第33节）。</li>\n<li><b>三种能量。</b>《三正道》说，肉身靠从食物里摄取的“食氣”维持；神经系统和“七魄”的运作靠“地气”；来自更深层的“炁”联动身体、左右它的行为。</li>\n<li><b>七魄。</b>第二节折叠里说的“自动驾驶”，在《失忆的归途》第十二章里叫作七魄。《三正道》把它译成感知力、直觉力、生育力、抵抗力、排毒、解毒、新陈代谢七种能力。</li>\n<li><b>三魂。</b>对应交感与副交感神经节、大脑、肠脑三套中枢（Y1H-1 第2册），《三正道》又称之为灵魂意识、小我意识、生物意识。日常运转主要依靠三魂中的人魂（Y8-2 第372节）。</li>\n<li><b>“都是我”。</b>《三正道》说，它们<span class=\"q\">各自有各自的利益趋向与诉求，包括七魄在内，都是“我”</span>。这是“身体载具我”这个名字最直接的出处。</li>\n<li><b>云端之后。</b>第一节折叠里引用的“云端笔记本电脑”之后，原文接着说，载具里只有全套的维生系统和两魂，主体并不在载具内（Y1-4 第708节）。</li>\n<li><b>正身五步。</b>清理创伤、扩充脉道、增容电池、和合阴阳、沟通天地（《三正道》正身篇）。第六节的三个练习，可以看作第一步之前的地基。</li>\n<li><b>能量的滑坡。</b>长期的意识频率低潮、能量紊乱，会使身体从健康滑向亚健康，再到功能性疾病，最后变成器质性病变（JY3 第123节）。</li>\n<li><b>助缘病与业力病。</b>第五节折叠里说“并不是所有的病都是自己作出来的”，原文用的是这两个词：“助缘病”是演给某人看的，“业力病”是出生前自己安排下的伏笔（JY3 第123节）。</li>\n<li><b>疗愈梦。</b>第六节折叠里说的睡前交托，原文称为疗愈梦：入睡前静心专注地许愿，把角色的心愿交给更深的内在体系（Y5-1《或然自己》）。</li>\n<li><b>内证。</b>《内证观察笔记》以向内观察的方式描述脏腑经络：五藏六腑各自运化一种真气供给全身。十二条经脉像十二支军队，五藏六腑是它们的处理器，经络是它们的通信网。作者认为，内证的门槛不在技巧：“<span class=\"q\">内证，在中国古代，不是技术，而是道德的产物。或者内证本身就是道德。</span>”书中另有一句，几乎是第六节“本气虚而神过用”的注脚：“<span class=\"q\">元神喜静，识神喜动。识神动则情欲盛，情欲盛则耗散元精，进而耗散元神。</span>”（中编，第159页）</li>\n<li><b>《与神对话》。</b>书中说，人往往要到死亡的那一刻，才看清身体、思想和更深的那一层之中，谁才是真正的主人。</li>\n</ul>\n</div></details><details class=\"bv-fold\" id=\"bv-cmp\"><summary>其他传统怎样看身体？</summary><div class=\"bv-fold-body\">\n<p>许多传统都认真对待过身体。它们的共同点，是都看见了身体有自己的秩序，不只是一件工具。分歧在于，身体之外还有没有别的什么。</p>\n<div class=\"bv-traditions\"><section class=\"bv-tradition\"><h5>中医</h5><dl><div><dt>怎样看身体</dt><dd>形神合一；脏腑如十二官；顺应四时</dd></div><div><dt>与本体系相通</dt><dd>身体自有秩序；形与神俱</dd></div><div><dt>与本体系的分歧</dt><dd>以形神一体为主，较少讨论身体之外的意识层次</dd></div></dl></section><section class=\"bv-tradition\"><h5>《与神对话》</h5><dl><div><dt>怎样看身体</dt><dd>人是三合一的存在；身体是经验的载体</dd></div><div><dt>与本体系相通</dt><dd>身体是“经验”的那一环，你无法成为不曾经验的东西</dd></div><div><dt>与本体系的分歧</dt><dd>以三者合一为终点；本体系更重三者各司其职、彼此配合</dd></div></dl></section><section class=\"bv-tradition\"><h5>普莱斯纳</h5><dl><div><dt>怎样看身体</dt><dd>人既“是”身体，又“有”身体</dd></div><div><dt>与本体系相通</dt><dd>“载具”与“我”的双重性</dd></div><div><dt>与本体系的分歧</dt><dd>止于对人的描述，不讨论身体之外的意识</dd></div></dl></section><section class=\"bv-tradition\"><h5>梅洛-庞蒂</h5><dl><div><dt>怎样看身体</dt><dd>身体不是被意识驾驶的机器，而是我们通向世界的媒介</dd></div><div><dt>与本体系相通</dt><dd>身体是我们拥有一个世界的方式</dd></div><div><dt>与本体系的分歧</dt><dd>本体系认为身体之外还有意识的层次</dd></div></dl></section><section class=\"bv-tradition\"><h5>蒙田</h5><dl><div><dt>怎样看身体</dt><dd>认识自己，要从经验和身体开始</dd></div><div><dt>与本体系相通</dt><dd>通过体验认识自己</dd></div><div><dt>与本体系的分歧</dt><dd>以怀疑和自我观察为主，不建立意识的层次</dd></div></dl></section><section class=\"bv-tradition\"><h5>尼采</h5><dl><div><dt>怎样看身体</dt><dd>身体是一个大理性；“自身”住在身体里，它就是身体</dd></div><div><dt>与本体系相通</dt><dd>身体比理智更有智慧</dd></div><div><dt>与本体系的分歧</dt><dd>尼采把“自身”放进身体；本体系把身体看作三个我之一</dd></div></dl></section><section class=\"bv-tradition\"><h5>达马西奥</h5><dl><div><dt>怎样看身体</dt><dd>情绪和自我感，起源于大脑对身体状态的映射</dd></div><div><dt>与本体系相通</dt><dd>身体是“我”的地基；身体先知道</dd></div><div><dt>与本体系的分歧</dt><dd>他认为意识由身体产生；本体系认为意识不只由此产生</dd></div></dl></section><section class=\"bv-tradition\"><h5>佛教四念处</h5><dl><div><dt>怎样看身体</dt><dd>观身、观受，是修行的起点</dd></div><div><dt>与本体系相通</dt><dd>第六节的练习一</dd></div><div><dt>与本体系的分歧</dt><dd>以观身不净、破除身见为目的；本体系以合作为目的</dd></div></dl></section></div>\n</div></details></section><details class=\"bv-fold\" id=\"bv-refs\"><summary>出处与参考</summary><div class=\"bv-fold-body\">\n<ol class=\"refs\">\n<li>细雨资料：编号沿用资料库体例（如 JY3 第123节即《早期课精要萃取III》第123节），见各处引文和括注。</li>\n<li>尼尔·唐纳德·沃尔什《与神对话》，李继宏译，江西人民出版社，2015。</li>\n<li>Jane Roberts, <i>Seth Speaks</i> (1972)，第八章，第532节；<i>The Nature of Personal Reality</i> (1974)，第651节；<i>The Individual and the Nature of Mass Events</i> (1981)，第一章；<i>The Way Toward Health</i> (1997)。私人课引文见细雨资料 Y7-4。</li>\n<li>《黄帝内经·素问》：上古天真论、灵兰秘典论、举痛论、生气通天论、四气调神大论、五脏生成。《难经·六十一难》。张仲景《伤寒论·序》。苏轼《题西林壁》。</li>\n<li>李辛《精神健康讲记》，中医古籍出版社，2019。</li>\n<li>无名氏述《内证观察笔记》（增订本），广西师范大学出版社，2011。</li>\n<li>Cole, J. (1995). <i>Pride and a Daily Marathon</i>. MIT Press.</li>\n<li>Huffington, A. (2014). <i>Thrive</i>; (2016). <i>The Sleep Revolution</i>.</li>\n<li>史铁生《我与地坛》（1991）；《病隙碎笔》（2002）。</li>\n<li>Plessner, H. (1941). <i>Lachen und Weinen</i>.</li>\n<li>Merleau-Ponty, M. (1945). <i>Phénoménologie de la perception</i>.</li>\n<li>Wiener, N. (1950). <i>The Human Use of Human Beings</i>.</li>\n<li>Sender, R., &amp; Milo, R. (2021). The distribution of cellular turnover in the human body. <i>Nature Medicine</i>, 27, 45–48.</li>\n<li>Bernard, C. (1878). <i>Leçons sur les phénomènes de la vie communs aux animaux et aux végétaux</i>. Cannon, W. B. (1932). <i>The Wisdom of the Body</i>.</li>\n<li>Siffre, M. (1963). <i>Hors du temps</i>. 2017 年诺贝尔生理学或医学奖：Jeffrey C. Hall, Michael Rosbash, Michael W. Young.</li>\n<li>Wood, W., Quinn, J. M., &amp; Kashy, D. A. (2002). Habits in everyday life. <i>Journal of Personality and Social Psychology</i>, 83, 1281–1297.</li>\n<li>Keller, H. (1903). <i>The Story of My Life</i>, Chapter IV.</li>\n<li>Bhalla, M., &amp; Proffitt, D. R. (1999). Visual–motor recalibration in geographical slant perception. <i>JEP: Human Perception and Performance</i>；质疑见 Firestone, C., &amp; Scholl, B. J. (2016). <i>Behavioral and Brain Sciences</i>。</li>\n<li>Bechara, A., Damasio, H., Tranel, D., &amp; Damasio, A. R. (1997). Deciding advantageously before knowing the advantageous strategy. <i>Science</i>；质疑见 Maia, T. V., &amp; McClelland, J. L. (2004). <i>PNAS</i>。</li>\n<li>Craig, A. D. (2002). How do you feel? Interoception. <i>Nature Reviews Neuroscience</i>, 3, 655–666. Barrett, L. F. (2017). <i>How Emotions Are Made</i>.</li>\n<li>Montaigne, M. de. <i>Essais</i>, III.13 « De l’expérience ».</li>\n<li>Wagner, U., Gais, S., Haider, H., Verleger, R., &amp; Born, J. (2004). Sleep inspires insight. <i>Nature</i>, 427, 352–355.</li>\n<li>Plutarch, <i>Life of Demosthenes</i>, 6–11.</li>\n<li>Parks, R., with Haskins, J. (1992). <i>Rosa Parks: My Story</i>.</li>\n<li>Bem, D. J. (1972). Self-perception theory. <i>Advances in Experimental Social Psychology</i>, 6. Bandura, A. (1997). <i>Self-Efficacy: The Exercise of Control</i>.</li>\n<li>Ibarra, H. (2003). <i>Working Identity</i>. Harvard Business School Press.</li>\n<li>Dispenza, J. (2012). <i>Breaking the Habit of Being Yourself</i>. Dixon, L. J., Hornsey, M. J., &amp; Hartley, N. (2023). “The Secret” to success? The psychology of belief in manifestation. <i>Personality and Social Psychology Bulletin</i>.</li>\n<li>Murakami, H. (2004). The Art of Fiction No. 182. <i>The Paris Review</i>, 170；村上春树《当我谈跑步时我谈些什么》（2007）。</li>\n<li>Alexander, F. M. (1932). <i>The Use of the Self</i>.</li>\n<li>Kiecolt-Glaser, J. K., et al. (1995). Slowing of wound healing by psychological stress. <i>The Lancet</i>.</li>\n<li>Matisse, H. (1947). <i>Jazz</i>. Tériade.</li>\n<li>Watson, N. F., et al. (2015). <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4442216/\" rel=\"noopener noreferrer\" target=\"_blank\">Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society</a>. <i>Journal of Clinical Sleep Medicine</i>, 11(6), 591–592.</li>\n</ol>\n</div></details></article></div><nav class=\"bv-page-turn\" aria-label=\"篇章导航\"><a href=\"#/knowing/body-self\"><small>上一页</small><span>← 身体载具我导读</span></a><a href=\"#/knowing/body-self/experience\"><small>继续阅读</small><span>第二部 · 理解身体 →</span></a></nav></div>", "experience": "<div class=\"page-shell knowing-page bv-page bv-part-page\"><nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/\">首页</a><span>/</span><a href=\"#/ren\">人道</a><span>/</span><a href=\"#/knowing\">认识自己</a><span>/</span><a href=\"#/knowing/body-self\">身体载具我</a><span>/</span><span aria-current=\"page\">理解身体</span></nav><nav class=\"bv-chapter-nav\" aria-label=\"身体载具我阅读路径\"><a href=\"#/knowing/body-self\" >导读</a><a href=\"#/knowing/body-self/recognition\" ><small>01</small>认识身体</a><a href=\"#/knowing/body-self/experience\" aria-current=\"page\"><small>02</small>理解身体</a><a href=\"#/knowing/body-self/cooperation\" ><small>03</small>与身体合作</a></nav><header class=\"bv-hero\"><div><p class=\"bv-kicker\">身体载具我 · 第二部 / 02</p><h1>理解身体</h1><p class=\"bv-question\">体验与创造，怎样在这里发生？</p><p class=\"bv-deck\">世界经由身体成为体验；选择经由行动进入现实，新的体验又使我们重新认识自己。</p></div><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/experience.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"双手塑造陶器，触碰与调整带来新的形状\"><figcaption>理解身体</figcaption></figure></header><details class=\"bv-fold bv-onpage\"><summary>本篇目录</summary><nav aria-label=\"本篇章节\"><a href=\"#bv-s03\" data-scroll=\"bv-s03\">03 通过身体，世界成为我的体验</a><a href=\"#bv-s04\" data-scroll=\"bv-s04\">04 通过身体，选择成为现实中的自己</a></nav></details><div class=\"bv-prose\"><details class=\"bv-fold bv-reading-note\"><summary>怎样阅读本篇的研究与思想来源？</summary><div class=\"bv-fold-body\"><p>主线正文可以独立阅读。带“+”的部分默认收起，展开可阅读延伸案例、研究讨论与原资料。</p><p><span class=\"lv l1\">研究参考</span>引用研究与科学资料，需结合研究范围理解；<span class=\"lv l2\">结论有争议</span>提示已有不同解释；<span class=\"lv l3\">体系主张</span>提示三道哲学或所引资料的哲学解释。三者的提示会一直保留。</p></div></details><article aria-label=\"理解身体正文\"><p class=\"intro\">《三道哲学》的主旨句是：生命的意义在于通过体验认识自己，通过选择创造自己。这一部看身体在这两件事里做了什么。</p><p>《与神对话》把人看作三合一的存在：身体、思想，以及更深的那一层。它用三个词概括三者的关系：一个构思，一个创造，一个经验，三者循环不息。身体是“经验”的那一环。书里还有一句更短的话：“<span class=\"q\">你无法成为你不曾经验的东西</span>”。</p><p>体验和创造，就在这一环上接在一起。</p><section aria-labelledby=\"bv-s03\" class=\"bv-section\"><h3 id=\"bv-s03\"><span class=\"n\">03</span>通过身体，世界成为我的体验</h3>\n<h4>一个“体”字</h4>\n<p>中文里，和“知道”有关的许多词，都带着一个“体”字：体验，体会，体察，体悟，体谅。造这些词的人似乎早就认定，有一类知道，只能经由身体得到。读一百遍讲游泳的书，不如下一次水。</p>\n<h4>井边的那个字</h4>\n<p>1887 年春天，海伦·凯勒还不满七岁。她在一岁多时因病失去了视力和听力，此后几年，世界对她几乎是封闭的。老师安妮·沙利文每天在她手心里拼写单词，她能模仿那些手势，却不明白它们是什么。</p>\n<p>有一天，沙利文带她到井房。清凉的水从她一只手上流过，沙利文在她另一只手心里拼出 w-a-t-e-r。她忽然明白了：手上这个流动的、清凉的东西，就叫“水”。她后来在自传里写道，是那个字把她唤醒了。离开井房时，她急着去摸每一样东西，每样东西都有了名字。那一天，她学会了“母亲”“父亲”“妹妹”“老师”。</p>\n<p>唤醒她的，是同时发生的两件事：手上真实的水，和手心里的那个字。身体的体验和意义，在同一刻接上了。我们大多数人不会经历这样戏剧性的一刻，可我们对世界的理解，最初都是这样进来的。</p>\n<figure aria-label=\"世界、身体与我\" class=\"fig\">\n<p class=\"ttl\">世界经由身体，成为我的体验</p>\n<div class=\"flow\">\n<div class=\"st\"><h6>世界</h6>人，事，地方，<br/>一杯水，一座山</div>\n<div aria-hidden=\"true\" class=\"ar\">⇄</div>\n<div class=\"st\"><h6>身体</h6>看见，听见，触碰，运动<br/>紧张，舒展，疼痛，愉悦</div>\n<div aria-hidden=\"true\" class=\"ar\">⇄</div>\n<div class=\"st\"><h6>我</h6>认出自己的喜爱、需要、<br/>能力和边界</div>\n</div>\n<figcaption>箭头是双向的：世界经由身体进来，我也经由身体回应世界。</figcaption>\n</figure>\n<h4>站在哪里，就看见什么</h4>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">横看成岭侧成峰，远近高低各不同。不识庐山真面目，只缘身在此山中。</p><cite class=\"src\">——苏轼《题西林壁》</cite></blockquote>\n<p>苏轼写的是庐山，说的也是人和世界相遇的方式：身体站在哪里，你就看见什么。身体的状态，同样会改变你看见的世界。有研究发现，背着沉重背包的人、刚跑完步很累的人，估计面前一段坡有多陡时，会说得比实际更陡。<span class=\"lv l2\">结论有争议</span>世界有多远、多重、多难，常常最先是由身体量出来的。</p>\n<h4>反应，常常先于语言</h4>\n<p>身体的反应，常常走在语言前面。1997 年的一个纸牌实验里，受试者还说不出哪两副牌危险，伸手去拿危险的牌时，手心的皮肤电反应就已经升高了。<span class=\"lv l2\">结论有争议</span>神经科学里有一个词叫“内感受”，指大脑对身体内部状态的感知：心跳、呼吸、胃肠、体温。许多研究者认为，我们说的“感受”，很大一部分是从这些身体信号里建构出来的。<span class=\"lv l2\">结论有争议</span></p>\n<p>融资会开始前，你的胃先缩紧了，大脑还在组织理由，身体已经先作出了反应。它可能与眼前的风险有关，也可能与陌生、期待、过去的经历或疲劳有关。反应已经发生，它意味着什么，还需要理解。</p>\n<details class=\"bv-fold\"><summary>“身体先知道”，证据有多硬？</summary><div class=\"bv-fold-body\">\n<p><b>纸牌实验。</b>这是达马西奥团队 1997 年的研究。桌上四副牌，其中两副看起来回报高，长期玩下去却会输钱。受试者还说不清哪两副危险时，伸手去拿它们，皮肤电反应就已经升高。后来有研究者质疑，认为受试者其实比他们说出来的知道得更多。所以这个实验能说明身体反应常常很早出现，至于“身体比意识先知道”，证据还有争论。</p>\n<p><b>坡度实验。</b>疲惫或负重的人把坡估得更陡，这是普罗菲特等人在 1999 年前后的一组研究。批评者认为，受试者可能是猜到了实验的意图，才说得更陡。这场争论还没有结论。</p>\n<p><b>内感受。</b>巴瑞特等研究者主张，情绪是大脑根据身体状态和过去经验做出的预测。这是目前很有影响的理论，但并非定论。</p>\n<p>这一节用这些研究，只是为了说明一件日常经验里随处可见的事：身体参与了我们怎样感受和判断世界。</p>\n</div></details>\n<h4>在经历里认出自己</h4>\n<p>十六世纪的法国人蒙田，三十八岁辞去公职，回到庄园的塔楼里写作。他说，他研究得最多的题目就是他自己。四十多岁起，他得了肾结石，疼痛反复发作，伴随了他的后半生。他在《随笔集》里一遍遍写这病：发作时他怎样害怕，怎样忍耐，疼痛退去以后，又怎样重新觉得活着是好的。他发现，病痛在人身上占据的地方，往往跟人让给它的地方一样大。经历多了，他对死亡也没有从前那样怕了。</p>\n<p>《随笔集》的最后一篇叫《论经验》，里面有这样的句子：</p>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">我跳舞的时候就跳舞，睡觉的时候就睡觉。</p><cite class=\"src\">——蒙田《随笔集》第三卷第十三章《论经验》</cite></blockquote>\n<p>一个用一生研究自己的人，最后把自我认识落在了跳舞和睡觉上。</p>\n<p>你也许也有过这样的时刻。第一次在会上说出真实的反对意见，声音在抖，说完却发现自己比想象中站得稳。爬一座山，腿已经软了，心里却还想再往上走一段。照顾生病的家人几个星期，才知道自己能有多大的耐心，也知道这份耐心在哪里用完。这些认识，事先坐在书桌前想不出来。它们是在经历里，从身体里长出来的。</p>\n<p>中医师李辛对“学习”的说法，正好说的是这件事：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">真正的学习不光是看书、学习他人的经验，也是睁开自己的双眼，打开心，自主思考，理解人我和世界，在与所有流经我们的人、事、物互动的过程中，更多地认识、熟悉自己和身体，了解自己的真实需求，找到自己的“原点”，展开自己的“地图”。</p><cite class=\"src\">——李辛《精神健康讲记》缘起</cite></blockquote>\n<h4>也有来自更深处的讯息</h4>\n<p>在三道哲学的理解中，经由身体被感受到的，还可能有来自更深意识的讯息。<span class=\"lv l3\">体系主张</span></p>\n<blockquote class=\"bv-quote\"><p class=\"q\">来自身体的信号不断传递给它，在某些层面上它与身体保持着即时的接触，尤其是在生存层面上。</p><cite class=\"src\">——Y7-3 第307节</cite></blockquote>\n<p>这里的“它”，指资料中的内在自我，本体系将它与内在意识我联系起来。引文描述的是身体的信号传向内在自我；三道哲学进一步把两者的联系理解为双向的，并把身体视作体会内在讯息的通道。一种说不出理由的轻松、一阵挥之不去的抗拒，都可以成为停下来观察的起点。单凭这种感觉，还不能认定讯息来自哪里。第五节会讲怎样理解与回应，第三章再展开内在意识我。</p>\n<p>这类资料也重视梦境的体验（Y1-4 第705节）。《与神对话》将睡眠描述为更深的那一层暂时离开身体去“充电”。这是书中对意识与睡眠的解释。下面关于睡眠与解题的实验，研究的是睡眠后的表现，不能据此判断这种“离开”是否发生。</p>\n<details class=\"bv-fold\"><summary>睡一觉，真的能想通事情吗？</summary><div class=\"bv-fold-body\">\n<p>2004 年，德国的一项研究让受试者做一组数字题，题目里藏着一条可以让人瞬间解题的捷径。练习之后，一组人睡了一觉，另一组人醒着度过同样长的时间。再做题时，睡过觉的人里约有 59% 发现了这条捷径，一直醒着的人里只有约 23%。<span class=\"lv l2\">结论有争议</span></p>\n<p>这是单项研究，样本不大，后续研究的结果也不完全一致。它至少说明，睡眠并不只是“关机”。</p>\n</div></details>\n<p class=\"lines\">认识自己，需要进入生活，<br/>也需要听见生活在身体里留下的回应。</p>\n<div class=\"check\"><b>自查</b>最近一次让你“认出自己”的经历，你的身体当时在做什么？</div>\n</section><section aria-labelledby=\"bv-s04\" class=\"bv-section\"><h3 id=\"bv-s04\"><span class=\"n\">04</span>通过身体，选择成为现实中的自己</h3>\n<h4>选择要落到身体上</h4>\n<p>你决定做一个有耐心的人。这个决定在心里只需要一秒。它真正成形，却是在下一次交谈里：对方说到一半，你没有打断；你察觉到自己想反驳，停了一拍；你的语气比以前慢了一点。耐心最后长在停顿、呼吸和声音里。</p>\n<p>选择成为一个创造者也一样。它要落进一次次具体的工作：几点坐下来，坐多久，卡住的时候是起身走开，还是再写一页。身份就这样，从一个想法，慢慢变成一种生活方式。《与神对话》把身体称作：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">它是光荣的载体，让你们能够经验你们用你们的精神所创造的实在</p><cite class=\"src\">——《与神对话》第1卷</cite></blockquote>\n<p>你在心里想好的样子，要经由身体，才能真正被经验到。书里还说，创造要生效，身体、思想和更深的那一层，要在思维、话语和行动中一致（《与神对话》第3卷）。反过来也一样。有人一边熬夜、不运动，一边盼着靠意识让自己瞬间康复，原资料对这种心愿的判断很干脆：“<span class=\"q\">这心愿不会被运作执行——你根本什么都没有做出自身的调整与改变</span>”（Y3-2 第98节）。</p>\n<details class=\"bv-fold\"><summary>德摩斯梯尼怎样把选择练进身体？</summary><div class=\"bv-fold-body\">\n<p>两千三百多年前的雅典，有一个年轻人想成为演说家。据普鲁塔克记载，他天生嗓音微弱，吐字含混，说长一点的句子就喘不上气。第一次在公民大会上发言，他被台下哄笑，只好退场。</p>\n<p>他没有放弃。他在地下修了一间练习室，一待就是几个月，为了逼自己不出门，还把头发剃掉一半。他含着石子练习吐字，一边跑步、一边爬陡坡一边背诵，在家里对着一面大镜子练手势。这个人就是德摩斯梯尼，后来成为古希腊最著名的演说家。</p>\n<p>成为演说家的选择，最初只发生在心里。之后的许多年，这个选择一点一点落进了他的舌头、呼吸和声音。每一次在镜子前、在坡道上的练习，都带回一份反馈：哪里还含混，哪里已经清楚。他一边练，一边重新认识自己，也一边成了自己选的那个人。</p>\n</div></details><h4>一个没有站起来的人</h4>\n<p>1955 年 12 月 1 日，美国阿拉巴马州的蒙哥马利，四十二岁的罗莎·帕克斯下班后坐在公交车上。司机要她给白人乘客让座，她没有站起来，随后被捕。这件事引发了持续一年多的蒙哥马利公交抵制运动。</p>\n<p>后来常有人说，她那天是太累了。她自己的说法是，那天她唯一累的，是一再让步。坐在座位上，这个最简单的姿势，在那一刻成了一个选择的全部表达。选择要靠身体表达出来，有时是一句话出口时的声音，有时只是没有站起来。</p>\n<section class=\"bv-explorer\" id=\"bv-choice-lab\"><p class=\"bv-kicker\">把关系放进一个场景</p><h4>一次“更有耐心”的选择，怎样成为生活？</h4><div role=\"tablist\" aria-label=\"一次“更有耐心”的选择，怎样成为生活？\"><button type=\"button\" role=\"tab\" id=\"bv-choice-lab-tab-0\" aria-controls=\"bv-choice-lab-panel-0\" aria-selected=\"true\" tabindex=\"0\">01 选择</button><button type=\"button\" role=\"tab\" id=\"bv-choice-lab-tab-1\" aria-controls=\"bv-choice-lab-panel-1\" aria-selected=\"false\" tabindex=\"-1\">02 行动</button><button type=\"button\" role=\"tab\" id=\"bv-choice-lab-tab-2\" aria-controls=\"bv-choice-lab-panel-2\" aria-selected=\"false\" tabindex=\"-1\">03 体验</button><button type=\"button\" role=\"tab\" id=\"bv-choice-lab-tab-3\" aria-controls=\"bv-choice-lab-panel-3\" aria-selected=\"false\" tabindex=\"-1\">04 再认识</button></div><div class=\"bv-explorer-panels\"><div role=\"tabpanel\" id=\"bv-choice-lab-panel-0\" aria-labelledby=\"bv-choice-lab-tab-0\" ><h5>选择</h5><p>先选定愿意体现的品质，而不是要求自己从此没有情绪。</p><p class=\"bv-example\">我愿意更有耐心地理解对方。</p></div><div role=\"tabpanel\" id=\"bv-choice-lab-panel-1\" aria-labelledby=\"bv-choice-lab-tab-1\" hidden><h5>行动</h5><p>把品质落在一次身体能够做出的回应里。</p><p class=\"bv-example\">对方说到一半，我停一拍，让他把话讲完。</p></div><div role=\"tabpanel\" id=\"bv-choice-lab-panel-2\" aria-labelledby=\"bv-choice-lab-tab-2\" hidden><h5>体验</h5><p>留意身体当时怎样，也看现实里发生了什么。</p><p class=\"bv-example\">我仍然有些紧张，但听见了原先没有听懂的担心。</p></div><div role=\"tabpanel\" id=\"bv-choice-lab-panel-3\" aria-labelledby=\"bv-choice-lab-tab-3\" hidden><h5>再认识</h5><p>用这次经历修正认识，为下一次选择提供依据。</p><p class=\"bv-example\">原来耐心不要求没有冲动；我可以在冲动出现时留出一个停顿。</p></div></div></section><h4>一条双向的回路</h4>\n<figure aria-label=\"选择与反馈的回路\" class=\"fig\">\n<p class=\"ttl\">选择怎样经由身体，回到自己身上</p>\n<div class=\"loop\">\n<div class=\"st\"><h6>① 内在选择</h6>我要成为<br/>什么样的人</div>\n<div aria-hidden=\"true\" class=\"ar\">→</div>\n<div class=\"st body\"><h6>② 表达与行动</h6>语气、停顿、姿势，一次次具体的工作</div>\n<div aria-hidden=\"true\" class=\"ar\">↑</div>\n<div></div>\n<div aria-hidden=\"true\" class=\"ar\">↓</div>\n<div class=\"st\"><h6>④ 新的认识</h6>原来我能做到，<br/>原来我在乎这个</div>\n<div aria-hidden=\"true\" class=\"ar\">←</div>\n<div class=\"st body\"><h6>③ 实际体验</h6>身体当时怎样，<br/>世界怎样回应</div>\n<p class=\"c\">着色的两步，身体直接参与</p>\n</div>\n<figcaption>选择经由身体变成行动，行动带回的体验，又成为下一次选择的起点。</figcaption>\n</figure>\n<p>这条回路是双向的。选择经由身体变成行动，行动带回的体验，又反过来改变我们对自己的认识。心理学家贝姆提出过一个看法：人常常是看着自己做了什么，才推断出自己是谁、在乎什么。<span class=\"lv l1\">研究参考</span>班杜拉的研究也发现，亲手做成过一件事，是“我能做到”最可靠的来源。<span class=\"lv l1\">研究参考</span></p>\n<p>研究职业转型的学者伊瓦拉，访谈过许多换了人生方向的人。她发现，他们很少是先想清楚、再去做的。更常见的情形是先试着做一点，在做的过程里，才认出自己适合成为谁。</p>\n<p>显化类的作者也看到了这一面。乔·迪斯彭扎主张，在行动之前，先让身体在想象里感到“已经是”，好让身体也开始站到新的自己这一边。这是显化类的公开说法，不是研究结论。它关注的也是身体与改变的关系，但“想象中感到已经是”与“行动后形成新的自我认识”，是两个不同的主张，需要分别看待。</p>\n<h4>村上春树为什么跑步</h4>\n<p>1978 年，二十九岁的村上春树在神宫球场看棒球，忽然决定写小说。几年后，他转让了自己经营的爵士酒吧，成为专职作家，也在那段时间开始每天跑步。他在 2004 年的一次访谈里描述过写长篇时的作息：清晨四点起床，写五六个小时，下午跑十公里或游一千五百米，晚上九点睡。他说，体力和艺术感受力一样必要。</p>\n<p>成为小说家的那个决定，后来变成了每天四点起床、每天跑十公里的身体。一个身份能不能长久地活下去，要看它有没有变成一种身体过得下去的生活。</p>\n<details class=\"bv-fold\"><summary>三个我与创造九层，怎样联系？</summary><div class=\"bv-fold-body\">\n<p>读过《创造自己》的人，可能会想把这条回路对到九层上。两者是两张图。三个我回答“一个人可以从哪几个角度来认识”，九层回答“一个人怎样把选择一步步变成现实”，两张图不能逐项对应。九层里有两处和身体最近：05 情绪，在预演时让身体真的感到一次“已经是”；09 行动，每一次行动都是投给新身份的一票。这一节讲的，是身体在整条回路里的位置。</p>\n</div></details><details class=\"bv-fold\"><summary>行动真的会改变“我是谁”吗？</summary><div class=\"bv-fold-body\">\n<p><b>自我知觉。</b>贝姆 1972 年提出，当内心的态度还不清楚时，人会像旁观者一样，从自己的行为去推断自己。比如发现自己连续三个周末都在做同一件事，才意识到自己真喜欢它。<span class=\"lv l1\">研究参考</span></p>\n<p><b>自我效能。</b>班杜拉认为，“我能做到”的信心有四个来源：亲身做成、看到相似的人做成、别人的鼓励，以及身体和情绪的状态。其中亲身做成的经验最有力。注意第四个来源：同一件事，身体紧绷时人会更怀疑自己。<span class=\"lv l1\">研究参考</span></p>\n<p><b>先做后知。</b>伊瓦拉在《转型》（2003）里，把这叫作“先试后学”：用小的实验、新的关系和短期项目去试探可能的自己，而不是等想清楚了再动。这是基于访谈的研究，适合当作启发来读。</p>\n<p>这些研究说的是“我是谁”的认识怎样被行动改变，它们并不处理更深的问题：选择最初从哪里来。那是第三章的事。</p>\n</div></details>\n<details class=\"bv-fold\"><summary>显化说的“让身体先成为”，该怎样理解？</summary><div class=\"bv-fold-body\">\n<p>迪斯彭扎在《打破做自己的习惯》（2012）里说，人长期重复同样的情绪，身体就会“记住”这种状态，变得比头脑更快地回到旧的自己。所以他主张，在冥想和想象里，让身体提前感受新的自己。</p>\n<p>这和九层 05 情绪里的做法相通：预演时让身体真的感到一次“已经是”。在这套实践的理解里，预演是让人尝试感受新的自己；它能带来什么改变，还要回到实际行动中观察。</p>\n<p>它不能代替行动和反馈。有研究调查了上千名美国人，发现越相信显化的人，越觉得自己会成功，却也更相信一夜暴富，经历过破产的比例更高。这项研究只说明相关，不能说明因果。<span class=\"lv l2\">结论有争议</span>它提醒的是：只在想象里成为，身体没有真正去做，回路就断了。</p>\n</div></details>\n<h4>方向，也会在经历里改变</h4>\n<p>这条回路走过几次，改变的可能不只是能力。一个人原来想成为演说家，练习之后，发现自己更珍惜的是帮助别人把话说清楚；一个人原来把成功理解为不断扩大事业，身体条件改变后，开始认真看待陪伴与创作。身体带来的体验，使原来的愿望有机会被重新理解。</p>\n<p>所以，身体参与创造自己，也包括让选择接受生活的检验。有些方向，要走进去以后，才知道是否属于自己；有些方向仍然珍贵，却需要换一种身体能够持续的走法。</p>\n<p class=\"lines\">我正在怎样生活，<br/>也在参与塑造我正在成为谁。</p>\n<div class=\"check\"><b>自查</b>你想成为的那个人，在你这一周的身体里，留下了什么痕迹？</div>\n</section><details class=\"bv-fold\" id=\"bv-refs\"><summary>出处与参考</summary><div class=\"bv-fold-body\">\n<ol class=\"refs\">\n<li>细雨资料：编号沿用资料库体例（如 JY3 第123节即《早期课精要萃取III》第123节），见各处引文和括注。</li>\n<li>尼尔·唐纳德·沃尔什《与神对话》，李继宏译，江西人民出版社，2015。</li>\n<li>Jane Roberts, <i>Seth Speaks</i> (1972)，第八章，第532节；<i>The Nature of Personal Reality</i> (1974)，第651节；<i>The Individual and the Nature of Mass Events</i> (1981)，第一章；<i>The Way Toward Health</i> (1997)。私人课引文见细雨资料 Y7-4。</li>\n<li>《黄帝内经·素问》：上古天真论、灵兰秘典论、举痛论、生气通天论、四气调神大论、五脏生成。《难经·六十一难》。张仲景《伤寒论·序》。苏轼《题西林壁》。</li>\n<li>李辛《精神健康讲记》，中医古籍出版社，2019。</li>\n<li>无名氏述《内证观察笔记》（增订本），广西师范大学出版社，2011。</li>\n<li>Cole, J. (1995). <i>Pride and a Daily Marathon</i>. MIT Press.</li>\n<li>Huffington, A. (2014). <i>Thrive</i>; (2016). <i>The Sleep Revolution</i>.</li>\n<li>史铁生《我与地坛》（1991）；《病隙碎笔》（2002）。</li>\n<li>Plessner, H. (1941). <i>Lachen und Weinen</i>.</li>\n<li>Merleau-Ponty, M. (1945). <i>Phénoménologie de la perception</i>.</li>\n<li>Wiener, N. (1950). <i>The Human Use of Human Beings</i>.</li>\n<li>Sender, R., &amp; Milo, R. (2021). The distribution of cellular turnover in the human body. <i>Nature Medicine</i>, 27, 45–48.</li>\n<li>Bernard, C. (1878). <i>Leçons sur les phénomènes de la vie communs aux animaux et aux végétaux</i>. Cannon, W. B. (1932). <i>The Wisdom of the Body</i>.</li>\n<li>Siffre, M. (1963). <i>Hors du temps</i>. 2017 年诺贝尔生理学或医学奖：Jeffrey C. Hall, Michael Rosbash, Michael W. Young.</li>\n<li>Wood, W., Quinn, J. M., &amp; Kashy, D. A. (2002). Habits in everyday life. <i>Journal of Personality and Social Psychology</i>, 83, 1281–1297.</li>\n<li>Keller, H. (1903). <i>The Story of My Life</i>, Chapter IV.</li>\n<li>Bhalla, M., &amp; Proffitt, D. R. (1999). Visual–motor recalibration in geographical slant perception. <i>JEP: Human Perception and Performance</i>；质疑见 Firestone, C., &amp; Scholl, B. J. (2016). <i>Behavioral and Brain Sciences</i>。</li>\n<li>Bechara, A., Damasio, H., Tranel, D., &amp; Damasio, A. R. (1997). Deciding advantageously before knowing the advantageous strategy. <i>Science</i>；质疑见 Maia, T. V., &amp; McClelland, J. L. (2004). <i>PNAS</i>。</li>\n<li>Craig, A. D. (2002). How do you feel? Interoception. <i>Nature Reviews Neuroscience</i>, 3, 655–666. Barrett, L. F. (2017). <i>How Emotions Are Made</i>.</li>\n<li>Montaigne, M. de. <i>Essais</i>, III.13 « De l’expérience ».</li>\n<li>Wagner, U., Gais, S., Haider, H., Verleger, R., &amp; Born, J. (2004). Sleep inspires insight. <i>Nature</i>, 427, 352–355.</li>\n<li>Plutarch, <i>Life of Demosthenes</i>, 6–11.</li>\n<li>Parks, R., with Haskins, J. (1992). <i>Rosa Parks: My Story</i>.</li>\n<li>Bem, D. J. (1972). Self-perception theory. <i>Advances in Experimental Social Psychology</i>, 6. Bandura, A. (1997). <i>Self-Efficacy: The Exercise of Control</i>.</li>\n<li>Ibarra, H. (2003). <i>Working Identity</i>. Harvard Business School Press.</li>\n<li>Dispenza, J. (2012). <i>Breaking the Habit of Being Yourself</i>. Dixon, L. J., Hornsey, M. J., &amp; Hartley, N. (2023). “The Secret” to success? The psychology of belief in manifestation. <i>Personality and Social Psychology Bulletin</i>.</li>\n<li>Murakami, H. (2004). The Art of Fiction No. 182. <i>The Paris Review</i>, 170；村上春树《当我谈跑步时我谈些什么》（2007）。</li>\n<li>Alexander, F. M. (1932). <i>The Use of the Self</i>.</li>\n<li>Kiecolt-Glaser, J. K., et al. (1995). Slowing of wound healing by psychological stress. <i>The Lancet</i>.</li>\n<li>Matisse, H. (1947). <i>Jazz</i>. Tériade.</li>\n<li>Watson, N. F., et al. (2015). <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4442216/\" rel=\"noopener noreferrer\" target=\"_blank\">Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society</a>. <i>Journal of Clinical Sleep Medicine</i>, 11(6), 591–592.</li>\n</ol>\n</div></details></article></div><nav class=\"bv-page-turn\" aria-label=\"篇章导航\"><a href=\"#/knowing/body-self/recognition\"><small>上一页</small><span>← 第一部 · 认识身体</span></a><a href=\"#/knowing/body-self/cooperation\"><small>继续阅读</small><span>第三部 · 与身体合作 →</span></a></nav></div>", "cooperation": "<div class=\"page-shell knowing-page bv-page bv-part-page\"><nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/\">首页</a><span>/</span><a href=\"#/ren\">人道</a><span>/</span><a href=\"#/knowing\">认识自己</a><span>/</span><a href=\"#/knowing/body-self\">身体载具我</a><span>/</span><span aria-current=\"page\">与身体合作</span></nav><nav class=\"bv-chapter-nav\" aria-label=\"身体载具我阅读路径\"><a href=\"#/knowing/body-self\" >导读</a><a href=\"#/knowing/body-self/recognition\" ><small>01</small>认识身体</a><a href=\"#/knowing/body-self/experience\" ><small>02</small>理解身体</a><a href=\"#/knowing/body-self/cooperation\" aria-current=\"page\"><small>03</small>与身体合作</a></nav><header class=\"bv-hero\"><div><p class=\"bv-kicker\">身体载具我 · 第三部 / 03</p><h1>与身体合作</h1><p class=\"bv-question\">怎样让整个自己共同生活？</p><p class=\"bv-deck\">从察觉、辨认到回应，让方向、现实安排与身体需要形成能够持续的生活。</p></div><figure class=\"bv-illustration\"><img src=\"/assets/body-self-parts/cooperation.webp\" width=\"1536\" height=\"1024\" loading=\"eager\" decoding=\"async\" alt=\"照料花园的人在树下停步，工具与清水放在身旁\"><figcaption>与身体合作</figcaption></figure></header><details class=\"bv-fold bv-onpage\"><summary>本篇目录</summary><nav aria-label=\"本篇章节\"><a href=\"#bv-s05\" data-scroll=\"bv-s05\">05 听见身体，也学会理解它</a><a href=\"#bv-s06\" data-scroll=\"bv-s06\">06 让身体进入我的人生安排</a><a href=\"#bv-epilogue\" data-scroll=\"bv-epilogue\">尾声 · 它从不需要知道自己叫什么</a></nav></details><div class=\"bv-prose\"><details class=\"bv-fold bv-reading-note\"><summary>怎样阅读本篇的研究与思想来源？</summary><div class=\"bv-fold-body\"><p>主线正文可以独立阅读。带“+”的部分默认收起，展开可阅读延伸案例、研究讨论与原资料。</p><p><span class=\"lv l1\">研究参考</span>引用研究与科学资料，需结合研究范围理解；<span class=\"lv l2\">结论有争议</span>提示已有不同解释；<span class=\"lv l3\">体系主张</span>提示三道哲学或所引资料的哲学解释。三者的提示会一直保留。</p></div></details><article aria-label=\"与身体合作正文\"><section aria-labelledby=\"bv-s05\" class=\"bv-section\"><h3 id=\"bv-s05\"><span class=\"n\">05</span>听见身体，也学会理解它</h3>\n<h4>一位失声的演员</h4>\n<p>十九世纪九十年代，澳大利亚有一位叫亚历山大的朗诵演员，演出时常常声音嘶哑，后来严重到几乎发不出声。他看了好几位医生，喉咙查不出毛病，休息几天能好一些，一上台又坏了。</p>\n<p>他决定自己找原因。他在几面镜子前一遍遍朗诵，看自己说话时身体在做什么。看了很久，他发现，每次一开口，他的头就往后、往下压，脖子和后背一起绷紧，而他自己从来没有察觉。当他学会在开口之前先停一下，不让这套动作自动跑起来，声音就回来了。后来他去了伦敦，把这套办法教了几十年，就是今天说的“亚历山大技巧”。</p>\n<p>他用镜子做了三件事：先看见身体正在做什么，再弄清它和问题有什么关系，最后才决定怎样回应。和身体合作，用的也是这三个动作。</p>\n<figure aria-label=\"察觉、辨认、回应\" class=\"fig\">\n<p class=\"ttl\">听懂身体的三个动作</p>\n<div class=\"flow\">\n<div class=\"st\"><h6>察觉</h6>此刻发生了什么？<br/>哪里紧，哪里松，<br/>有余力还是在硬撑</div>\n<div aria-hidden=\"true\" class=\"ar\">→</div>\n<div class=\"st\"><h6>辨认</h6>它可能和什么有关？\n      <div class=\"sub3\"><span>身体与环境</span><span>心理与行为</span><span>处境与方向</span></div></div>\n<div aria-hidden=\"true\" class=\"ar\">→</div>\n<div class=\"st\"><h6>回应</h6>休息，表达，<br/>调整安排，<br/>或进一步了解</div>\n</div>\n<figcaption>同一种紧绷，可能需要完全不同的回应。先察觉，再辨认，最后才回应。</figcaption>\n</figure>\n<h4>察觉：此刻发生了什么</h4>\n<p>李辛把这一步叫作觉察：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">我把对身体的感受，进入我们的意识，称之为对身体的觉察。</p><cite class=\"src\">——李辛《精神健康讲记》第一篇</cite></blockquote>\n<p>听身体，不需要仪器，也不需要医学知识。可以从三个最简单的问题开始，随时都能问：</p>\n<ol class=\"five\">\n<li><b>它此刻是松的，还是紧的？</b>肩膀、下巴、胸口，哪里正绷着？</li>\n<li><b>它此刻有余力，还是在硬撑？</b></li>\n<li><b>它此刻想靠近什么，想躲开什么？</b>一个人，一件事，一个地方。</li>\n</ol>\n<p>问完不急着做什么，只是听见。察觉也不要求你先平静下来。李辛有一段话说得很实在：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">我们可以一边吵架，一边清楚知道自己在生气，知道身体紧张、情绪涌动。按照传统中医的观点，这就是“神气”相对清明的状态。</p><cite class=\"src\">——李辛《精神健康讲记》第一篇</cite></blockquote>\n<details class=\"bv-fold\"><summary>中医怎样从外面读身体？</summary><div class=\"bv-fold-body\">\n<ul class=\"plain\">\n<li><b>里面的状态，显在外面。</b>《黄帝内经·素问·五脏生成》说，心显在脸色，肺显在皮毛，肝显在筋和指甲，脾显在肌肉和嘴唇，肾显在骨和头发。</li>\n<li><b>读懂身体是一门功夫。</b>“<span class=\"q qc\">望而知之谓之神，闻而知之谓之圣，问而知之谓之工，切脉而知之谓之巧。</span>”（《难经·六十一难》）</li>\n<li><b>念头也会落到身体上。</b>李辛描述过一种状态：人坐在那里看书，想法却很多，像站在十字路口，车来车往，每个字都认识，意思却看不进去。中医把这叫作“神不定”。</li>\n</ul>\n</div></details>\n<h4>辨认：先看状态</h4>\n<p>听见以后，要弄清它可能和什么有关。辨认之前，先看一眼自己处在什么状态，因为状态会改变你听到的东西。原资料用“意识频率”描述一个人感到开阔或受困的状态：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">意识频率越高，可见范围越大；相反地，那些觉得没路可走或死路一条的人，其意识频率就已经跌落到谷底了，仅剩下鼠目寸光。</p><cite class=\"src\">——S2-1《三正道》</cite></blockquote>\n<p>在这里，可以把“意识频率”读作描述体验的用语：此刻，我还能看见多少条路。它不是本章测量的生理频率，也不用于给人划分高低。很多创业者都熟悉这样的夜晚。凌晨三点，账上的钱只够撑三个月，你躺在床上，越想越觉得没有出路。第二天睡醒，吃过早饭，同样的处境，你忽然又想得出两三个办法。处境没有变，变的是你能看见的范围。</p>\n<p>身体透支时，人可能更难看见其他办法。李辛从中医的角度描述过一种相近的处境：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">内在的封闭模式固化之后，会使一个人在生命能量很低的时候，没有多余的力量去寻找出路了，只能解决基本存活的问题。</p><cite class=\"src\">——李辛《精神健康讲记》第一篇</cite></blockquote>\n<p>连勇气也是这样。李辛有一句很短的话：“<span class=\"q\">勇气是依靠阳气支持的。</span>”很多时候，你缺的不是决心，是力气。所以凌晨三点得出的结论，最好等睡醒以后再看一遍。</p>\n<h4>辨认：从具体条件开始</h4>\n<p>状态看过了，再找原因。设想一台智能车，在高速上总是跑偏：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">这原因可能是司机操纵不当，可能是车辆本身机械故障，也可能是车载自动驾驶系统出现问题。此时就应具体问题具体分析。</p><cite class=\"src\">——Y8-2 第371节</cite></blockquote>\n<p>这个比喻提醒我们，同一种表现可能有不同原因。车、司机和自动驾驶并不逐项对应三个我；身体的自动调节本身就属于身体。重要的是把可能的原因分开看。</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">患者持续多年上班就头晕，很可能是工装的领口小，压迫到颈动脉</p><cite class=\"src\">——Y2-4 第33节</cite></blockquote>\n<p>原资料也用虱子和骨折提醒读者，身体的问题有具体的现实条件（Y7-5 第325节）。领口的例子同样只是提醒我们留意环境，不能据此判断头晕的原因。理解身体的不适，可以从三个方向提出问题：</p>\n<ol class=\"steps\">\n<li><b>身体与环境</b>：近期睡眠、饮食、活动和环境有什么变化？是否需要就医检查？</li>\n<li><b>心理与行为</b>：在什么情境里更明显？是否与压力、旧习惯或反复的担忧一起出现？</li>\n<li><b>处境与方向</b>：眼下的安排是否适合自己？有没有需要表达的困难、调整的关系或重新理解的目标？</li>\n</ol>\n<p>这三个方向可以同时考虑，涉及意义的思考也可以与检查、治疗并行。检查没有找到原因，并不意味着原因就属于更深的意识。原资料提醒，不要“<span class=\"q\">学了灵性，什么都归咎给意识卡顿</span>”（Y2-4 第33节）；它也鼓励人在接受帮助时，继续照顾自己的生活安排（参见 Y4-2 第159节）。理解自己，可以从李辛所说的“<span class=\"q\">就是自己的心得定</span>”开始，不急着给不适一个解释。</p>\n<p>在赛斯的资料里，也有把个人的症状与其人生处境联系起来的解释：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">在某种程度上，症状确实代表了谨慎。直到他再次确定自己的方向，他都不愿意行动。</p><cite class=\"src\">——Y7-4（私人课）</cite></blockquote>\n<p>这是赛斯对一个具体个案的解释，不能直接套用到另一个人身上。它可以引出关于生活处境的问题，但不能代替对病因的了解。还要留心一件事。《与神对话》提醒过，有些“感受”其实是“<span class=\"q\">伪装成感受的思维</span>”。一阵不安，可能是身体在报信，也可能只是旧的念头穿上了感受的外衣。</p>\n<h4>紧张，也可能发生在值得做的事上</h4>\n<p>第一次在会上说出反对意见，声音发抖，胸口发紧。你可能很想把话咽回去。但这份紧张，可以同时伴随一个清楚的判断：这件事值得说，我只是不习惯这样做。</p>\n<p>先把感觉与解释分开记下来：“我胸口紧”是此刻的感受；“这说明我不该说”是对它的解释。然后看情境：有没有具体的危险？这份紧张是否也出现在其他陌生场合？在安全、可承受的情况下，试着把意见说短一点，或先和一个可信任的人谈谈，再观察自己的变化。</p>\n<p>一次尝试不必得出结论。把行动前、行动中和之后的感受放在一起看，再结合事实与他人的回应，才更容易理解这份紧张。轻松也一样：它可能来自适合自己，也可能只是暂时避开了困难。</p>\n<p>身体的讯号可以作为自我觉察的线索，但不是诊断，也不能代替就医。这是底线。</p>\n<details class=\"bv-fold\"><summary>一个冲动，怎样分辨它来自哪一层？</summary><div class=\"bv-fold-body\">\n<p>赛斯在《个人与群体事件的本质》里说，一个人不可能一边不信任自己的冲动，一边又信任自己。但冲动有层次，有两种东西常被混为一谈：</p>\n<ul class=\"plain\">\n<li><b>身体的直觉</b>：关于危险，关于眼前这个人，关于这口食物能不能吃。它快、具体，面向生存。这种“直觉力”，本来就是身体的自动功能之一（S2-1《三正道》）。</li>\n<li><b>内在的灵感</b>：关于方向，关于这件事值不值得做。它慢、整体，面向意义。</li>\n</ul>\n<p>这些区分来自本体系对冲动的理解。快或慢、具体或整体，都不足以让我们单独判定它来自哪一层。饿了想吃，累了想睡，先认真照料；关于人生方向的感受，则需要放回经历、事实与持续的选择中辨认。第三章会进一步讨论这件事。</p>\n</div></details>\n<details class=\"bv-fold\"><summary>生病，是不是我的错？</summary><div class=\"bv-fold-body\">\n<blockquote class=\"bv-quote\"><p class=\"q\">所有的疾病首先都是在精神中被创造出来的。</p><cite class=\"src\">——《与神对话》第1卷</cite></blockquote>\n<p>这是《与神对话》对疾病的精神性解释。它可以引出一个反思的问题：这段经历，和我心里发生的事有什么关系？但这不等于已经知道疾病由什么造成。<span class=\"lv l3\">体系主张</span></p>\n<p>JY3 第123节还用“助缘病”“业力病”解释疾病与人生体验的关系，包括陪伴别人的功课，以及出生前安排的体验。这些都属于资料内部的信念解释，不能据此判定一个具体的人为什么患病。</p>\n<p>本章保留这些资料，是为了呈现它们怎样理解生命。是否借此思考自身经历，由读者自己决定。患病不能证明一个人的思想、品格或意识出了问题；我们也不需要先为病痛找到精神上的理由，才有资格获得照顾与治疗。</p>\n</div></details>\n<section class=\"bv-explorer\" id=\"bv-signal-lab\"><p class=\"bv-kicker\">把关系放进一个场景</p><h4>同样是紧绷，回应为什么不同？</h4><div role=\"tablist\" aria-label=\"同样是紧绷，回应为什么不同？\"><button type=\"button\" role=\"tab\" id=\"bv-signal-lab-tab-0\" aria-controls=\"bv-signal-lab-panel-0\" aria-selected=\"true\" tabindex=\"0\">01 先照料</button><button type=\"button\" role=\"tab\" id=\"bv-signal-lab-tab-1\" aria-controls=\"bv-signal-lab-panel-1\" aria-selected=\"false\" tabindex=\"-1\">02 小步尝试</button><button type=\"button\" role=\"tab\" id=\"bv-signal-lab-tab-2\" aria-controls=\"bv-signal-lab-panel-2\" aria-selected=\"false\" tabindex=\"-1\">03 寻求帮助</button></div><div class=\"bv-explorer-panels\"><div role=\"tabpanel\" id=\"bv-signal-lab-panel-0\" aria-labelledby=\"bv-signal-lab-tab-0\" ><h5>先照料</h5><p>先看具体的身体与环境条件，给自己一项可实行的照顾。</p><p class=\"bv-example\">如果近期一直透支，先调整休息与安排，再持续观察。</p></div><div role=\"tabpanel\" id=\"bv-signal-lab-panel-1\" aria-labelledby=\"bv-signal-lab-tab-1\" hidden><h5>小步尝试</h5><p>当事情值得做、情境安全且身体可承受时，紧张可以伴随一次小的行动。</p><p class=\"bv-example\">第一次提出反对意见，可以先说清一个事实，再观察行动前后的变化。</p></div><div role=\"tabpanel\" id=\"bv-signal-lab-panel-2\" aria-labelledby=\"bv-signal-lab-tab-2\" hidden><h5>寻求帮助</h5><p>持续、加重或原因不明的不适，需要进一步了解。</p><p class=\"bv-example\">安排就医与必要检查，不从一份紧张直接推定病因或人生方向。</p></div></div></section><h4>回应：同一种紧绷，不同的回应</h4>\n<p>辨认之后，才谈得上回应。同一种紧绷，可能需要完全不同的东西：</p>\n<ul class=\"plain\">\n<li><b>需要休息。</b>它只是累了。睡一觉，比任何分析都有用。</li>\n<li><b>需要表达。</b>有一句话一直没说。情绪被强压成忍耐、迟迟不被表达，最后很容易变成身体的症状。解法是先看见它，承认它，再设法释放它（Y9-5 第482节）。</li>\n<li><b>需要调整安排。</b>问题出在日程上：连续三周没有一个完整的周末，再怎么放松也没用。这一步，第六节细讲。</li>\n<li><b>需要进一步了解。</b>它持续很久，或者越来越重。这时该去看医生，做该做的检查。</li>\n</ul>\n<p>回应的语气也要紧。原资料说：“<span class=\"q\">当身体被温柔地看见，它也会温柔地回应</span>”（Y9-4 第476节）。</p>\n<details class=\"bv-fold\"><summary>情绪和压力，会怎样落到身体上？</summary><div class=\"bv-fold-body\">\n<p>外在角色我的情绪、压力和信念，身体全都收得到。李辛引过《黄帝内经》的一句话：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">所以《黄帝内经》说：“怒则气上，恐则气下，思则气结，喜则气缓，惊则气乱。”</p><cite class=\"src\">——李辛《精神健康讲记》第一篇，原文见《黄帝内经·素问·举痛论》</cite></blockquote>\n<p>喜悦和恐惧，坦然和焦虑，都会直接改变身体在化学层面的运作（JY3 第123节）。实验室里看得到这件事。1995 年的一项研究里，长期照护失智家人的人，手臂上一个小小的标准创口，平均要多花九天才愈合。<span class=\"lv l1\">研究参考</span></p>\n<p>赛斯说得更彻底：身体只能回应当下，对未来的担忧和对过去的反刍，都会干扰它的运作（《健康之道》）。你的身体，本来就是你的思想、情绪和诠释的物质化（《灵魂永生》）。</p>\n</div></details>\n<p class=\"lines\">身体的感受值得认真听，<br/>也值得耐心了解。</p>\n<div class=\"check\"><b>自查</b>你身上最常出现的一种紧绷，通常在提醒你什么？你一般怎样回应它？</div>\n</section><section aria-labelledby=\"bv-s06\" class=\"bv-section\"><h3 id=\"bv-s06\"><span class=\"n\">06</span>让身体进入我的人生安排</h3>\n<h4>倒下的那个早晨</h4>\n<p>2007 年，阿里安娜·赫芬顿创办《赫芬顿邮报》差不多两年，每天工作十八个小时左右，在办公室、演讲和采访之间连轴转。一天，她在办公桌前倒下，醒来时躺在地板上，颧骨摔断了，身边一摊血。接下来是几个星期的检查，医生最后给出的结论只有一个：疲劳过度。</p>\n<p>后来，她写了一本书重新定义成功，又写了一本书专门讲睡眠，最后离开了自己一手创办的公司。她的身体反对的，是一种安排：所有东西都排进了日程，只有它没有。</p>\n<h4>三种常见的安排</h4>\n<p>日常里真正管着身体的，是外在角色我。载具里负责运作这具身体的，就是角色我（JY3 第142节）。哪个需要先被满足，哪个可以推迟一段时间，也由它来定（Y6-3 第270节）。几点睡，吃什么，要不要去跑步，今晚要不要再撑一会儿，都是它在拍板。角色我有过强、过弱、平和三种状态（JY3 第142节），前两种，对应三种常见的安排。</p>\n<p><strong>不管它。</strong>设想一位每天只睡四个小时的创始人。他喝着第三杯咖啡开早会，午饭在会议间隙随便对付，体检报告收到就扔进抽屉。他以为自己在透支时间，其实透支的是身体。过劳的身心，最后是“<span class=\"q\">把青春卖给了资本，又花大价钱从资本手里象征性地购买医疗来续命</span>”（Y4-2 第161节）。一千八百年前，张仲景在《伤寒论》的序里，批评的是同一种人：</p>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外而悴其内。皮之不存，毛将安附焉？</p><cite class=\"src\">——张仲景《伤寒论·序》</cite></blockquote>\n<p>李辛把这种状态叫作“<span class=\"q\">本气虚而神过用</span>”：本来的能量就不够，还长期用心过度、用力过猛（《精神健康讲记》）。下一章会把这种状态叫作“入戏太深”，还会看到，他拿身体去换的东西，有一个共同的名字：名。老子早就问过一句：名与身孰亲？</p>\n<p><strong>优化它。</strong>过强还有一种更隐蔽的样子：手环记录心率变异和睡眠评分，每天吃一把补剂，按算法安排作息，体检报告做成表格逐年对比。这份“爱惜”，仍是角色我说了算，只是换了一套更聪明的工具。久而久之，人“<span class=\"q\">不再相信自己的感觉与身体的感受，而更相信科学仪器和书本上的公式</span>”（S2-4《世上练》）。学养生、买保健品，常常是在填一个内心的空洞（Y1-6 第744节）。越焦虑自己在变老，保养品用得越贵，反而越是在给细胞下“变老”的指令（Y5-2）。</p>\n<p><strong>被它接管。</strong>角色我太弱的时候，就会放纵身体，任由欲望当家（Y4-2 第160节）。吃、睡，外表和感官的享受，成了日子的全部。这种状态，可以叫作“被身体接管”。这不是身体的错。眼前的舒适可能与长期需要发生冲突；其中也可能有习惯、情绪和环境的影响，需要把这些因素一起看清。</p>\n<p>这三种安排各不相同，却都是有一方在搞一言堂。不管它和优化它，是角色我说了算；被它接管，是身体的欲望说了算。三种安排里，内在意识我都没有位置。而在这几方里，原资料说，“<span class=\"q\">最无奈的恐怕就是载具我了</span>”（Y4-2 第160节）。</p>\n<h4>当目标和身体起冲突</h4>\n<p>角色我平和的时候，既兼顾身体的真实需要，又跟随内在的热忱，在两者之间承上启下（JY3 第142节）。对身体来说，一位平和的管家做三件事：</p>\n<ol class=\"steps\">\n<li><b>把身体的需要排进日程。</b>睡眠、吃饭、活动，和会议一样写进日历，而且不轻易挪。</li>\n<li><b>听身体的提案。</b>每个人生路口，身体都会提出它的主张。好的管家会认真听这一份，哪怕最后没有照办。</li>\n<li><b>不搞一言堂。</b>身体可以反对，管家可以否决，但不能假装它没说话。“<span class=\"q\">有时内部的争执不是坏事，一言堂要不得</span>”（Y4-2 第165节）。</li>\n</ol>\n<p>冲突总会来：一个融资窗口，一次产品上线，一个病中的家人。这时能调的，不只有“撑”和“不撑”两个选项。</p>\n<figure aria-label=\"目标与身体冲突时可以调的四样\" class=\"fig\">\n<p class=\"ttl\">当目标和身体起冲突，可以调的有四样</p>\n<div class=\"vs\"><span>目标的要求</span><i>⇄</i><span>身体的余力</span></div>\n<div class=\"knobs\">\n<div><h6>节奏</h6>同样的总量，换一种分配：冲刺之后留出恢复</div>\n<div><h6>方法</h6>同样的结果，换一种做法：交出去，或做得更简单</div>\n<div><h6>期限</h6>同样的事，换一个时间：晚两周，往往无伤大局</div>\n<div><h6>目标本身</h6>先问内在意识我：这个方向，还是不是自己的</div>\n</div>\n<figcaption>多数时候，调前三样就够了。真要动目标，要问的是方向，而不是身体的忍耐力。</figcaption>\n</figure>\n<h4>身体条件不同的人</h4>\n<p>1941 年，七十出头的马蒂斯做了一次癌症大手术。命保住了，此后他大多数时间只能在床上和椅子上度过，长时间站在画架前已经做不到了。他改用剪刀，把刷好颜色的纸剪成形状，再请助手按他的指点钉到墙上。这些“剪纸”成了他晚年最重要的作品，1947 年出版的《爵士》就是其中之一。</p>\n<p>合作不要求身体达到某个标准。身体条件不同、正在生病、或者这一段时间实在没有余力的人，合作的样子也不同。它只要求从这具身体今天的真实状况出发，就像史铁生在两次透析之间写作，就像马蒂斯在床上拿起剪刀。</p>\n<h4>节律、活动与恢复</h4>\n<blockquote class=\"bv-quote\"><p class=\"q qc\">上古之人，其知道者，法于阴阳，和于术数，食饮有节，起居有常，不妄作劳，故能形与神俱，而尽终其天年，度百岁乃去。</p><cite class=\"src\">——《黄帝内经·素问·上古天真论》</cite></blockquote>\n<p>吃饭有节制，起居有规律，不胡乱地操劳，形和神才能在一起。形是身体，神是让身体活起来、看得清楚的那一份。“形与神俱”，是合作最好的样子。</p>\n<p>活动也是合作的一部分。赛斯多次叮嘱珍和罗，写作久坐之余要多做动功，让身体舒展开，尤其要多活动背部（JY3 第74节）。村上春树把跑步排进每天的日程，也是同一个道理。</p>\n<p>还要给恢复留出位置。李辛说：“<span class=\"q\">生命中要有适当部分的无所事事的空闲时间和心理状态。</span>”留白用不着休假。排满行程的旅行，仍然是紧张。散步，发呆，看看天，就够了。</p>\n<details class=\"bv-fold\"><summary>赛斯怎样看睡眠？</summary><div class=\"bv-fold-body\">\n<p>赛斯不主张一口气睡很久。他说，一次睡五个小时左右，得到的好处最多，再长并不会多出多少；把睡眠分成两段或几段，比一整段更有效，总时间也可以更少，其中最长的一段放在夜里。需要更多休息的人，可以再加一次两小时左右的小睡；夜里睡四个小时，再加两次小睡，也很好（《灵魂永生》第八章，第532节）。在《个人实相的本质》里，他建议夜里的那一段不要超过六个小时（第651节）。</p>\n<p>赛斯把这种睡法解释为顺应节律、提高睡眠的效用。这个解释属于他的资料，不能仅凭它认定分段睡眠更有效，或认定自己可以减少总睡眠。<span class=\"lv l3\">体系主张</span></p>\n<p>在他的解释里，分段睡眠还与记住梦境、连接白天和夜里的体验有关。本章把它保留为延伸阅读。一般实践先从保证充足睡眠、观察白天的状态开始；美国睡眠医学会与睡眠研究学会的联合共识建议，18—60 岁成年人规律地每晚睡眠至少七小时。<a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4442216/\" rel=\"noopener noreferrer\" target=\"_blank\">见联合共识</a>。</p>\n</div></details>\n<details class=\"bv-fold\"><summary>中医怎样讲节律与恢复？</summary><div class=\"bv-fold-body\">\n<ul class=\"plain\">\n<li><b>一天的节律。</b>“<span class=\"q qc\">平旦人气生，日中而阳气隆，日西而阳气已虚，气门乃闭。</span>”（《黄帝内经·素问·生气通天论》）早上升，中午盛，傍晚收。</li>\n<li><b>一年的节律。</b>四季各有作息，比如冬天要“<span class=\"q qc\">早卧晚起，必待日光</span>”（《黄帝内经·素问·四气调神大论》）。</li>\n<li><b>一生的节律。</b>《黄帝内经·素问·上古天真论》把人的一生按女子七年、男子八年一段来讲：女子二十八岁、男子三十二岁前后最强壮，女子三十五岁、男子四十岁前后开始走下坡路。</li>\n<li><b>恢复靠安静。</b>“<span class=\"q qc\">恬惔虚无，真气从之，精神内守，病安从来。</span>”（《黄帝内经·素问·上古天真论》）心里清静，不被杂念填满，身体的气就顺；精神守在里面，不往外散，病从哪里来？</li>\n</ul>\n</div></details>\n<h4>让内在的王归位</h4>\n<p>回到第二节那座朝廷。心之所以是君主，是因为“<span class=\"q qc\">神明出焉</span>”：一个人的清明，从这里出来。《黄帝内经·素问·灵兰秘典论》列完十二官，接着说“<span class=\"q qc\">主明则下安</span>”，“<span class=\"q qc\">主不明则十二官危</span>”：君主清明，下面就安稳；君主昏乱，十二个官职都有危险。</p>\n<p>三道哲学借这幅图景来理解三个我的合作：内在意识我像君王，引领方向；外在角色我像摄政王，处理现实安排；身体像整个王国，承载着生活。这里借用的是治理的比喻，并不把《内经》的“心”与内在意识我直接等同。原资料也用“多党执政”形容内部失去配合的消耗（JY3 第133节）。身体的疲惫与不适值得认真对待，但不能把一次生病直接解释为它在反对某个目标。</p>\n<p>如果把三个我的分工压成三句话，可以这样说：</p>\n<p class=\"lines big\">方向，由内在意识我引领；<br/>路，由外在角色我去走；<br/>走多快、走多远，要问身体载具我。</p>\n<p>第三句的关键是“问”。这个问，也包括听取身体带回的体验，重新认识原来的方向。有些选择，要走进去以后，才知道是否属于自己。所谓王归位，就是让内在的方向、现实的安排和身体的需要，慢慢形成一种能够共同生活的秩序。</p>\n<h4>三个练习</h4>\n<p>三个练习都很小，难的是天天做。</p>\n<p><strong>练习一：观察一次身体状态。</strong>早上或睡前花一分钟，问一遍那三个问题：松还是紧，有余力还是在硬撑，想靠近什么、想躲开什么。只观察，不评判。佛教讲修行从“观身”“观受”开始，说的就是这件事。如果愿意，可以把答案记下来。几周之后，规律会自己浮现：哪些人和事、哪些时段，总让它绷紧。记录是为了听懂它，不是为了管住它。</p>\n<p><strong>练习二：调整一项长期透支的安排。</strong>只选一项：睡眠，吃饭，久坐，或者日程里那段永远被挤掉的空白。改一件小事，坚持两周，比如每晚固定一个关电脑的时间，每坐九十分钟起来走五分钟。下周的日历上，先把睡眠、三餐和活动的时间填进去，再排会议。调整后，继续观察白天的精神与身体状态；这项练习的目标，是减少长期透支。</p>\n<p><strong>练习三：记录一次行动后的反馈。</strong>做完一件符合你所选身份的事，花两分钟写下三行：做的时候身体怎样，有劲还是没劲，紧还是松；这件事带回了什么体验；它让你对自己多知道了什么。这就是第四节那条回路的第三步和第四步。攒上几条，你会看见自己正在成为谁。</p>\n<details class=\"bv-fold\"><summary>睡前，可以对身体说些什么？</summary><div class=\"bv-fold-body\">\n<p>鲁柏（赛斯对珍·罗伯茨的称呼）有一个习惯：睡觉前，“<span class=\"q\">请求他的系统去轻松地继续其健康和自然的合作</span>”（Y4-2 第160节）。这本是一个初级的辅助方法，要紧的是它请身体继续合作的那种语气。</p>\n<p>静下来以后，还可以把一个心愿交给更深的内在。Y5-1《或然自己》把这描述为交给内在体系、在幕后运作的过程。这是资料的解释。也可以把睡前交托作为暂时放下反刍的一种个人仪式，醒来后仍继续行动与观察。至于跟身体说话的语气：</p>\n<blockquote class=\"bv-quote\"><p class=\"q\">说给身体的话，就好像是对挚友的低语，而非对机器的指令。</p><cite class=\"src\">——Y9-4 第476节</cite></blockquote>\n</div></details>\n<p class=\"lines\">把对身体的理解，<br/>变成对自己实际的照顾与支持。</p>\n<div class=\"check\"><b>自查</b>你的日程里，有没有哪一项，是一直在用身体去换的？</div>\n</section><section aria-labelledby=\"bv-epilogue\" class=\"bv-section\"><h2 id=\"bv-epilogue\">尾声 · 它从不需要知道自己叫什么</h2>\n<p>伊恩·沃特曼后来一直这样生活：每天醒来，先用眼睛找到自己的手和脚，再用意志把它们一件一件调动起来。这就是他每天的马拉松。</p>\n<p>赫芬顿后来说，那次倒下之后，她才开始重新定义什么叫成功。</p>\n<p>我们大多数人，不必像沃特曼那样每天用意志去跑这场马拉松，也不必等到倒在地上，才开始听身体说话。现在就可以开始。</p>\n<p>从身体开始，也有它的道理。它的回音最快：今晚睡得好不好，明早就知道。在这里学会的几件事，先听，再做决定，不搞一言堂，把感受、解释和行动后的反馈分开看，后面两章都用得上。另外两个我要做的任何事，也都要一具身体去走。</p>\n<p class=\"lines\">内在意识我在看，<br/>外在角色我在选，<br/>可是让任何一个选择真正落地的，只有它。</p>\n<p>你写下的每一行代码，签下的每一份合同，拥抱过的每一个人，都是经由它完成的。它不读你的商业计划书，也不在乎你的估值。它只是在你开会时替你呼吸，在你睡着后替你修补，在你逼自己再撑一夜的时候，安静地记下这笔账。</p>\n<p class=\"lines\">下一次，当你准备再熬一个通宵，<br/>不妨先停一秒，问问它：</p>\n<p class=\"lines big\">你还好吗？</p>\n<p>还有一件事。身体从来不需要知道自己叫什么。可是每天解释这些体验、制定目标、安排生活的，是另一个“我”。那一位有名字，有身份，有一长串“应该”。它又是怎样形成的？</p>\n<p class=\"lines\">下一章，我们去认识这一位：<br/>外在角色我。</p>\n<hr class=\"sep\"/>\n</section><details class=\"bv-fold\" id=\"bv-refs\"><summary>出处与参考</summary><div class=\"bv-fold-body\">\n<ol class=\"refs\">\n<li>细雨资料：编号沿用资料库体例（如 JY3 第123节即《早期课精要萃取III》第123节），见各处引文和括注。</li>\n<li>尼尔·唐纳德·沃尔什《与神对话》，李继宏译，江西人民出版社，2015。</li>\n<li>Jane Roberts, <i>Seth Speaks</i> (1972)，第八章，第532节；<i>The Nature of Personal Reality</i> (1974)，第651节；<i>The Individual and the Nature of Mass Events</i> (1981)，第一章；<i>The Way Toward Health</i> (1997)。私人课引文见细雨资料 Y7-4。</li>\n<li>《黄帝内经·素问》：上古天真论、灵兰秘典论、举痛论、生气通天论、四气调神大论、五脏生成。《难经·六十一难》。张仲景《伤寒论·序》。苏轼《题西林壁》。</li>\n<li>李辛《精神健康讲记》，中医古籍出版社，2019。</li>\n<li>无名氏述《内证观察笔记》（增订本），广西师范大学出版社，2011。</li>\n<li>Cole, J. (1995). <i>Pride and a Daily Marathon</i>. MIT Press.</li>\n<li>Huffington, A. (2014). <i>Thrive</i>; (2016). <i>The Sleep Revolution</i>.</li>\n<li>史铁生《我与地坛》（1991）；《病隙碎笔》（2002）。</li>\n<li>Plessner, H. (1941). <i>Lachen und Weinen</i>.</li>\n<li>Merleau-Ponty, M. (1945). <i>Phénoménologie de la perception</i>.</li>\n<li>Wiener, N. (1950). <i>The Human Use of Human Beings</i>.</li>\n<li>Sender, R., &amp; Milo, R. (2021). The distribution of cellular turnover in the human body. <i>Nature Medicine</i>, 27, 45–48.</li>\n<li>Bernard, C. (1878). <i>Leçons sur les phénomènes de la vie communs aux animaux et aux végétaux</i>. Cannon, W. B. (1932). <i>The Wisdom of the Body</i>.</li>\n<li>Siffre, M. (1963). <i>Hors du temps</i>. 2017 年诺贝尔生理学或医学奖：Jeffrey C. Hall, Michael Rosbash, Michael W. Young.</li>\n<li>Wood, W., Quinn, J. M., &amp; Kashy, D. A. (2002). Habits in everyday life. <i>Journal of Personality and Social Psychology</i>, 83, 1281–1297.</li>\n<li>Keller, H. (1903). <i>The Story of My Life</i>, Chapter IV.</li>\n<li>Bhalla, M., &amp; Proffitt, D. R. (1999). Visual–motor recalibration in geographical slant perception. <i>JEP: Human Perception and Performance</i>；质疑见 Firestone, C., &amp; Scholl, B. J. (2016). <i>Behavioral and Brain Sciences</i>。</li>\n<li>Bechara, A., Damasio, H., Tranel, D., &amp; Damasio, A. R. (1997). Deciding advantageously before knowing the advantageous strategy. <i>Science</i>；质疑见 Maia, T. V., &amp; McClelland, J. L. (2004). <i>PNAS</i>。</li>\n<li>Craig, A. D. (2002). How do you feel? Interoception. <i>Nature Reviews Neuroscience</i>, 3, 655–666. Barrett, L. F. (2017). <i>How Emotions Are Made</i>.</li>\n<li>Montaigne, M. de. <i>Essais</i>, III.13 « De l’expérience ».</li>\n<li>Wagner, U., Gais, S., Haider, H., Verleger, R., &amp; Born, J. (2004). Sleep inspires insight. <i>Nature</i>, 427, 352–355.</li>\n<li>Plutarch, <i>Life of Demosthenes</i>, 6–11.</li>\n<li>Parks, R., with Haskins, J. (1992). <i>Rosa Parks: My Story</i>.</li>\n<li>Bem, D. J. (1972). Self-perception theory. <i>Advances in Experimental Social Psychology</i>, 6. Bandura, A. (1997). <i>Self-Efficacy: The Exercise of Control</i>.</li>\n<li>Ibarra, H. (2003). <i>Working Identity</i>. Harvard Business School Press.</li>\n<li>Dispenza, J. (2012). <i>Breaking the Habit of Being Yourself</i>. Dixon, L. J., Hornsey, M. J., &amp; Hartley, N. (2023). “The Secret” to success? The psychology of belief in manifestation. <i>Personality and Social Psychology Bulletin</i>.</li>\n<li>Murakami, H. (2004). The Art of Fiction No. 182. <i>The Paris Review</i>, 170；村上春树《当我谈跑步时我谈些什么》（2007）。</li>\n<li>Alexander, F. M. (1932). <i>The Use of the Self</i>.</li>\n<li>Kiecolt-Glaser, J. K., et al. (1995). Slowing of wound healing by psychological stress. <i>The Lancet</i>.</li>\n<li>Matisse, H. (1947). <i>Jazz</i>. Tériade.</li>\n<li>Watson, N. F., et al. (2015). <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4442216/\" rel=\"noopener noreferrer\" target=\"_blank\">Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society</a>. <i>Journal of Clinical Sleep Medicine</i>, 11(6), 591–592.</li>\n</ol>\n</div></details></article></div><nav class=\"bv-page-turn\" aria-label=\"篇章导航\"><a href=\"#/knowing/body-self/experience\"><small>上一页</small><span>← 第二部 · 理解身体</span></a><a href=\"#/knowing/external-self\"><small>继续阅读</small><span>外在角色我 →</span></a></nav></div>"};
export function bodySelfPage(part=''){return pages[part]||'<div class="page-shell bv-page"><h1>未找到这一篇</h1><p><a href="#/knowing/body-self">回到身体载具我导读 →</a></p></div>';}
export function initBody(){
 const root=document.querySelector('.bv-page');if(!root)return;
 root.querySelectorAll('.bv-explorer').forEach(ex=>{
  const tabs=[...ex.querySelectorAll('[role="tab"]')],panels=[...ex.querySelectorAll('[role="tabpanel"]')];
  const activate=(index)=>{tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;panels[i].hidden=i!==index;});};
  tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(index));tab.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activate(n);tabs[n].focus();});});
 });
 root.querySelectorAll('a[data-scroll]').forEach(a=>a.addEventListener('click',()=>{const t=document.getElementById(a.dataset.scroll);if(t?.matches('details'))t.open=true;a.closest('.bv-onpage')?.removeAttribute('open');}));
}
